def build_processing_state(outer_visual_perception_state, inner_field_perception_state, perception_state):
    outer = dict(outer_visual_perception_state or {})
    inner = dict(inner_field_perception_state or {})
    perception = dict(perception_state or {})

    signal_relevance = float(outer.get("signal_relevance", 0.0) or 0.0)
    visual_contrast = float(outer.get("visual_contrast", 0.0) or 0.0)
    visual_coherence = float(outer.get("visual_coherence", perception.get("visual_coherence", 0.0)) or 0.0)
    visual_clarity = float(outer.get("visual_clarity", perception.get("visual_clarity", 0.0)) or 0.0)
    visual_object_stability = float(outer.get("visual_object_stability", perception.get("visual_object_stability", 0.0)) or 0.0)
    visual_form_novelty = float(outer.get("visual_form_novelty", perception.get("visual_form_novelty", 0.0)) or 0.0)
    visual_blindness = float(outer.get("visual_blindness", perception.get("visual_blindness", 0.0)) or 0.0)
    visual_form_pressure = float(outer.get("visual_form_pressure", perception.get("visual_form_pressure", 0.0)) or 0.0)
    visual_shape_resonance = float(outer.get("visual_shape_resonance", perception.get("visual_shape_resonance", 0.0)) or 0.0)
    visual_shape_fragility = float(outer.get("visual_shape_fragility", perception.get("visual_shape_fragility", 0.0)) or 0.0)
    market_balance = float(outer.get("market_balance", perception.get("market_balance", 0.0)) or 0.0)
    breakout_tension = float(outer.get("breakout_tension", perception.get("breakout_tension", 0.0)) or 0.0)
    spatial_bias = float(outer.get("spatial_bias", perception.get("spatial_bias", 0.0)) or 0.0)
    directional_bias = float(outer.get("directional_bias", perception.get("directional_bias", 0.0)) or 0.0)
    zone_proximity = float(perception.get("zone_proximity", 0.0) or 0.0)
    field_risk = abs(float(inner.get("field_mean_risk", 0.0) or 0.0))
    field_pressure = float(inner.get("field_regulation_pressure", 0.0) or 0.0)
    field_areal_count = int(inner.get("field_areal_count", 0) or 0)
    field_areal_stability_mean = float(inner.get("field_areal_stability_mean", 0.0) or 0.0)
    field_areal_pressure_mean = float(inner.get("field_areal_pressure_mean", 0.0) or 0.0)
    field_areal_drift = float(inner.get("field_areal_drift", 0.0) or 0.0)
    field_areal_dominance = float(inner.get("field_areal_dominance", 0.0) or 0.0)
    field_areal_fragmentation = float(inner.get("field_areal_fragmentation", 0.0) or 0.0)
    field_areal_coherence_mean = float(inner.get("field_areal_coherence_mean", 0.0) or 0.0)
    field_areal_conflict_mean = float(inner.get("field_areal_conflict_mean", 0.0) or 0.0)
    field_activity_island_count = int(inner.get("field_activity_island_count", 0) or 0)
    field_activity_island_mass_mean = float(inner.get("field_activity_island_mass_mean", 0.0) or 0.0)
    field_activity_island_mass_max = float(inner.get("field_activity_island_mass_max", 0.0) or 0.0)
    field_activity_island_activation_mean = float(inner.get("field_activity_island_activation_mean", 0.0) or 0.0)
    field_activity_island_pressure_mean = float(inner.get("field_activity_island_pressure_mean", 0.0) or 0.0)
    field_activity_island_coherence_mean = float(inner.get("field_activity_island_coherence_mean", 0.0) or 0.0)
    field_activity_island_context_reactivation_mean = float(inner.get("field_activity_island_context_reactivation_mean", 0.0) or 0.0)
    field_activity_island_spread = float(inner.get("field_activity_island_spread", 0.0) or 0.0)
    raw_field_perception_focus = float(inner.get("field_perception_focus", 0.0) or 0.0)
    raw_field_perception_clarity = float(inner.get("field_perception_clarity", 0.0) or 0.0)
    raw_field_perception_stability = float(inner.get("field_perception_stability", 0.0) or 0.0)
    raw_field_perception_fragmentation = float(inner.get("field_perception_fragmentation", 0.0) or 0.0)
    raw_field_perception_strain = float(inner.get("field_perception_strain", 0.0) or 0.0)
    dominant_activity_island_id = str(inner.get("dominant_activity_island_id", "-") or "-")
    field_perception_label = str(inner.get("field_perception_label", "quiet_field") or "quiet_field").strip().lower()
    uncertainty = float(perception.get("uncertainty_score", 0.0) or 0.0)
    novelty = float(perception.get("novelty_score", 0.0) or 0.0)
    structure_quality = float(perception.get("structure_quality", 0.0) or 0.0)
    structure_stability = float(perception.get("structure_stability", 0.0) or 0.0)

    visual_alignment = max(0.0, min(1.0, 1.0 - abs(spatial_bias - directional_bias)))
    areal_presence = max(0.0, min(1.0, float(field_areal_count) / 4.0))
    activity_island_presence = max(0.0, min(1.0, float(field_activity_island_count) / 4.0))
    coherent_field_bonus = 0.10 if field_perception_label == "coherent_perception_field" else 0.0
    active_field_bonus = 0.06 if field_perception_label == "active_perception_field" else 0.0
    memory_field_bonus = 0.05 if field_perception_label == "memory_reactivated_field" else 0.0
    strained_field_bonus = 0.10 if field_perception_label == "strained_field" else 0.0
    fragmented_field_bonus = 0.14 if field_perception_label == "fragmented_perception_field" else 0.0

    field_perception_pressure = max(
        0.0,
        min(
            1.0,
            (field_activity_island_pressure_mean * 0.24)
            + (raw_field_perception_strain * 0.22)
            + (raw_field_perception_fragmentation * 0.14)
            + (field_activity_island_activation_mean * 0.12)
            + (field_activity_island_spread * 0.08)
            + (activity_island_presence * 0.08)
            + (field_activity_island_context_reactivation_mean * 0.08)
            + strained_field_bonus
            + fragmented_field_bonus
            - (field_activity_island_coherence_mean * 0.08)
            - (raw_field_perception_clarity * 0.08),
        ),
    )

    field_perception_support = max(
        0.0,
        min(
            1.0,
            (field_activity_island_coherence_mean * 0.22)
            + (raw_field_perception_stability * 0.22)
            + (raw_field_perception_focus * 0.14)
            + (field_activity_island_mass_max * 0.10)
            + (field_activity_island_mass_mean * 0.08)
            + (field_activity_island_activation_mean * 0.10)
            + (field_activity_island_context_reactivation_mean * 0.08)
            + coherent_field_bonus
            + active_field_bonus
            + memory_field_bonus
            - (field_activity_island_pressure_mean * 0.12)
            - (raw_field_perception_fragmentation * 0.12)
            - (fragmented_field_bonus * 0.70),
        ),
    )

    field_perception_clarity = max(
        0.0,
        min(
            1.0,
            (field_perception_support * 0.38)
            + (raw_field_perception_clarity * 0.26)
            + (raw_field_perception_focus * 0.14)
            + (field_activity_island_coherence_mean * 0.12)
            + (max(0.0, 1.0 - field_perception_pressure) * 0.10),
        ),
    )

    processing_areal_tension = max(
        0.0,
        min(
            1.0,
            (field_areal_pressure_mean * 0.26)
            + (field_areal_conflict_mean * 0.24)
            + (field_areal_fragmentation * 0.22)
            + (field_perception_pressure * 0.10)
            + (min(1.0, field_areal_drift) * 0.12)
            + (areal_presence * 0.08)
            - (field_areal_coherence_mean * 0.10)
            - (field_areal_stability_mean * 0.08),
        ),
    )

    processing_areal_support = max(
        0.0,
        min(
            1.0,
            (field_areal_stability_mean * 0.28)
            + (field_areal_coherence_mean * 0.24)
            + (field_perception_support * 0.12)
            + (field_areal_dominance * 0.12)
            + (max(0.0, 1.0 - field_areal_fragmentation) * 0.16)
            + (max(0.0, 1.0 - min(1.0, field_areal_drift)) * 0.10)
            + (max(0.0, 1.0 - field_areal_conflict_mean) * 0.10),
        ),
    )

    processing_tension = max(
        0.0,
        min(
            1.0,
            (breakout_tension * 0.30)
            + (visual_contrast * 0.16)
            + (uncertainty * 0.14)
            + (field_pressure * 0.12)
            + (processing_areal_tension * 0.14)
            + (field_perception_pressure * 0.08)
            + (max(0.0, abs(spatial_bias) - market_balance) * 0.08)
            - (visual_coherence * 0.08)
            - (processing_areal_support * 0.06),
        ),
    )

    processing_load = max(
        0.0,
        min(
            1.0,
            (uncertainty * 0.22)
            + (novelty * 0.12)
            + (field_pressure * 0.14)
            + (field_risk * 0.08)
            + (visual_contrast * 0.06)
            + (breakout_tension * 0.12)
            + (processing_areal_tension * 0.16)
            + (field_perception_pressure * 0.10)
            + (max(0.0, 1.0 - visual_alignment) * 0.06)
            - (structure_stability * 0.04)
            - (market_balance * 0.06)
            - (visual_coherence * 0.08)
            - (processing_areal_support * 0.08),
        ),
    )

    processing_alignment = max(
        0.0,
        min(
            1.0,
            (visual_alignment * 0.28)
            + (market_balance * 0.18)
            + (visual_coherence * 0.14)
            + (signal_relevance * 0.08)
            + (zone_proximity * 0.06)
            + (structure_quality * 0.08)
            + (processing_areal_support * 0.14)
            + (field_perception_clarity * 0.08)
            - (processing_areal_tension * 0.10),
        ),
    )

    processing_stability = max(
        0.0,
        min(
            1.0,
            (signal_relevance * 0.18)
            + (max(0.0, 1.0 - uncertainty) * 0.14)
            + (max(0.0, 1.0 - min(1.0, field_risk)) * 0.10)
            + (structure_quality * 0.08)
            + (structure_stability * 0.08)
            + (market_balance * 0.12)
            + (visual_coherence * 0.10)
            + (processing_alignment * 0.10)
            + (processing_areal_support * 0.16)
            + (field_perception_clarity * 0.08)
            - (processing_tension * 0.10)
            - (processing_areal_tension * 0.10),
        ),
    )

    processing_readiness = max(
        0.0,
        min(
            1.0,
            (processing_stability * 0.44)
            + (max(0.0, 1.0 - processing_load) * 0.24)
            + (processing_alignment * 0.16)
            + (processing_areal_support * 0.16)
            + (field_perception_clarity * 0.08)
            - (field_perception_pressure * 0.06),
        ),
    )

    return {
        "processing_load": float(processing_load),
        "processing_stability": float(processing_stability),
        "processing_readiness": float(processing_readiness),
        "processing_alignment": float(processing_alignment),
        "processing_tension": float(processing_tension),
        "processing_areal_tension": float(processing_areal_tension),
        "processing_areal_support": float(processing_areal_support),
        "visual_clarity": float(visual_clarity),
        "visual_object_stability": float(visual_object_stability),
        "visual_form_novelty": float(visual_form_novelty),
        "visual_blindness": float(visual_blindness),
        "visual_form_pressure": float(visual_form_pressure),
        "visual_shape_resonance": float(visual_shape_resonance),
        "visual_shape_fragility": float(visual_shape_fragility),
        "field_perception_pressure": float(field_perception_pressure),
        "field_perception_support": float(field_perception_support),
        "field_perception_clarity": float(field_perception_clarity),
        "field_perception_focus": float(raw_field_perception_focus),
        "field_perception_stability": float(raw_field_perception_stability),
        "field_perception_fragmentation": float(raw_field_perception_fragmentation),
        "field_perception_strain": float(raw_field_perception_strain),
        "dominant_activity_island_id": str(dominant_activity_island_id),
        "field_perception_label": str(field_perception_label),
        "field_activity_island_count": int(field_activity_island_count),
        "field_activity_island_mass_mean": float(field_activity_island_mass_mean),
        "field_activity_island_mass_max": float(field_activity_island_mass_max),
        "field_activity_island_activation_mean": float(field_activity_island_activation_mean),
        "field_activity_island_pressure_mean": float(field_activity_island_pressure_mean),
        "field_activity_island_coherence_mean": float(field_activity_island_coherence_mean),
        "field_activity_island_context_reactivation_mean": float(field_activity_island_context_reactivation_mean),
        "field_activity_island_spread": float(field_activity_island_spread),
        "field_areal_count": int(field_areal_count),
        "field_areal_stability_mean": float(field_areal_stability_mean),
        "field_areal_pressure_mean": float(field_areal_pressure_mean),
        "field_areal_drift": float(field_areal_drift),
        "field_areal_dominance": float(field_areal_dominance),
        "field_areal_fragmentation": float(field_areal_fragmentation),
        "field_areal_coherence_mean": float(field_areal_coherence_mean),
        "field_areal_conflict_mean": float(field_areal_conflict_mean),
    }

def build_outcome_decomposition(bot, outcome_reason, position=None, experience_state=None):
    reason = str(outcome_reason or "").strip().lower()
    state = dict(experience_state or {})

    perception_quality = float(max(0.0, min(
        1.0,
        0.52
        + (float(getattr(bot, "focus_confidence", 0.0) or 0.0) * 0.22)
        - (float(getattr(bot, "last_signal_relevance", 0.0) or 0.0) * 0.10),
    )))
    felt_quality = float(max(0.0, min(
        1.0,
        0.50
        + (float(state.get("experience_regulation", 0.0) or 0.0) * 0.20)
        + (float(state.get("reflection_maturity", 0.0) or 0.0) * 0.12),
    )))
    thought_quality = float(max(0.0, min(
        1.0,
        0.50
        + (float(state.get("reflection_maturity", 0.0) or 0.0) * 0.22)
        + (float(state.get("load_bearing_capacity", 0.0) or 0.0) * 0.12),
    )))

    plan_quality = 0.50
    execution_quality = 0.50
    risk_fit_quality = 0.50

    if reason == "tp_hit":
        plan_quality += 0.18
        execution_quality += 0.18
        risk_fit_quality += 0.12
    elif reason == "sl_hit":
        plan_quality -= 0.16
        execution_quality -= 0.12
        risk_fit_quality -= 0.18
    elif reason in ("cancel", "timeout"):
        execution_quality -= 0.15
        plan_quality -= 0.08
    elif reason == "reward_too_small":
        plan_quality -= 0.18
    elif reason == "rr_too_low":
        plan_quality -= 0.16
        risk_fit_quality -= 0.12
    elif reason == "sl_distance_too_high":
        risk_fit_quality -= 0.20
        plan_quality -= 0.10

    if isinstance(position, dict):
        entry_price = abs(float(position.get("entry", 0.0) or 0.0))
        risk = abs(float(position.get("entry", 0.0) or 0.0) - float(position.get("sl", 0.0) or 0.0))
        if risk > 0.0:
            risk_fit_quality = float(max(0.0, min(1.0, risk_fit_quality - min(0.18, risk * 2.5))))
        risk_width_pressure = float(max(0.0, min(1.0, (risk / max(entry_price, 1e-9)) * 82.0))) if entry_price > 0.0 else 0.0
        if reason == "sl_hit" and risk_width_pressure > 0.0:
            plan_quality = float(max(0.0, min(1.0, plan_quality - (risk_width_pressure * 0.09))))
            execution_quality = float(max(0.0, min(1.0, execution_quality - (risk_width_pressure * 0.05))))
            risk_fit_quality = float(max(0.0, min(1.0, risk_fit_quality - (risk_width_pressure * 0.10))))
    else:
        risk_width_pressure = 0.0

    attempt_density = float(state.get("attempt_density", 0.0) or 0.0)
    overtrade_pressure = float(state.get("overtrade_pressure", 0.0) or 0.0)
    context_quality = float(state.get("context_quality", 0.0) or 0.0)

    plan_quality = float(max(0.0, min(1.0, plan_quality - (overtrade_pressure * 0.10) + (context_quality * 0.08))))
    execution_quality = float(max(0.0, min(1.0, execution_quality - (attempt_density * 0.08) - (overtrade_pressure * 0.10) + (context_quality * 0.10))))
    felt_quality = float(max(0.0, min(1.0, felt_quality - (overtrade_pressure * 0.12) + (context_quality * 0.10))))
    thought_quality = float(max(0.0, min(1.0, thought_quality - (attempt_density * 0.06) + (context_quality * 0.08))))

    return {
        "perception_quality": float(max(0.0, min(1.0, perception_quality))),
        "felt_quality": float(max(0.0, min(1.0, felt_quality))),
        "thought_quality": float(max(0.0, min(1.0, thought_quality))),
        "plan_quality": float(max(0.0, min(1.0, plan_quality))),
        "execution_quality": float(max(0.0, min(1.0, execution_quality))),
        "risk_fit_quality": float(max(0.0, min(1.0, risk_fit_quality))),
        "attempt_density": float(attempt_density),
        "overtrade_pressure": float(overtrade_pressure),
        "context_quality": float(context_quality),
        "risk_width_pressure": float(risk_width_pressure),
        "reason": str(reason or "-"),
    }

def build_experience_packet_feedback(
    bot,
    outcome_reason,
    position=None,
    outcome_decomposition=None,
    experience_state=None,
    form_development_state=None,
):
    reason = str(outcome_reason or "").strip().lower()
    outcome = dict(outcome_decomposition or {})
    experience = dict(experience_state or {})
    form_development = dict(form_development_state or {})
    position_state = dict(position or {}) if isinstance(position, dict) else {}
    meta = dict(position_state.get("meta", {}) or {}) if isinstance(position_state.get("meta", {}), dict) else {}
    meta_regulation = dict(meta.get("meta_regulation_state", {}) or {}) if isinstance(meta.get("meta_regulation_state", {}), dict) else {}
    if not meta_regulation and bot is not None:
        meta_regulation = dict(getattr(bot, "meta_regulation_state", {}) or {})
    neurochemical = dict(meta_regulation.get("neurochemical_state", {}) or {}) if isinstance(meta_regulation.get("neurochemical_state", {}), dict) else {}
    if not neurochemical and bot is not None:
        neurochemical = dict(getattr(bot, "neurochemical_state", {}) or {})
    bearing_context = dict(meta.get("bearing_context", {}) or {}) if isinstance(meta.get("bearing_context", {}), dict) else {}
    form_state = _extract_outcome_form_symbol_state(bot, position=position)

    def _b01(value, default=0.0):
        try:
            return _clip01(value)
        except Exception:
            return float(default)

    perception_quality = _b01(outcome.get("perception_quality", 0.50), default=0.50)
    felt_quality = _b01(outcome.get("felt_quality", 0.50), default=0.50)
    thought_quality = _b01(outcome.get("thought_quality", 0.50), default=0.50)
    plan_quality = _b01(outcome.get("plan_quality", 0.50), default=0.50)
    execution_quality = _b01(outcome.get("execution_quality", 0.50), default=0.50)
    risk_fit_quality = _b01(outcome.get("risk_fit_quality", 0.50), default=0.50)
    context_quality = _b01(outcome.get("context_quality", 0.0))
    attempt_density = _b01(outcome.get("attempt_density", 0.0))
    overtrade_pressure = _b01(outcome.get("overtrade_pressure", 0.0))
    risk_width_pressure = _b01(outcome.get("risk_width_pressure", 0.0))

    structure_quality = _b01(bearing_context.get("structure_quality", form_state.get("form_symbol_bearing", 0.0)))
    transfer_bearing = _b01(meta_regulation.get("transfer_bearing", 0.0))
    structure_action_bearing = _b01(meta_regulation.get("structure_action_bearing", 0.0))
    field_action_support = _b01(meta_regulation.get("field_action_support", 0.0))
    interpretation_quality = _b01(meta_regulation.get("interpretation_quality", perception_quality), default=perception_quality)
    load_bearing_capacity = _b01(experience.get("load_bearing_capacity", meta_regulation.get("load_bearing_capacity", 0.0)))
    reflection_maturity = _b01(experience.get("reflection_maturity", 0.0))
    experience_regulation = _b01(experience.get("experience_regulation", 0.0))

    perceptual_distance = _b01(meta_regulation.get("perceptual_distance", 0.0))
    object_contact_depth = _b01(meta_regulation.get("object_contact_depth", 0.0))
    field_attachment = _b01(meta_regulation.get("field_attachment", 0.0))
    release_capacity = _b01(meta_regulation.get("release_capacity", 0.0))
    inner_outer_alignment = _b01(meta_regulation.get("inner_outer_alignment", 0.0))
    selective_attention = _b01(meta_regulation.get("selective_attention", 0.0))
    diffuse_open_development_pressure = _b01(meta_regulation.get("diffuse_open_development_pressure", 0.0))
    action_clearance = _b01(meta_regulation.get("action_clearance", 0.0))
    action_inhibition = _b01(meta_regulation.get("action_inhibition", 0.0))
    regulated_courage = _b01(meta_regulation.get("regulated_courage", 0.0))
    curiosity_tone = _b01(meta_regulation.get("curiosity_tone", 0.0))
    fatigue_tone = _b01(meta_regulation.get("fatigue_tone", 0.0))
    pressure_release = _b01(experience.get("pressure_release", 0.0))
    emotional_decoupling = _b01(neurochemical.get("emotional_decoupling", meta_regulation.get("emotional_decoupling", 0.0)))

    form_process_quality = _b01(form_development.get("process_quality", 0.0))
    form_structural_support = _b01(form_development.get("structural_support", 0.0))
    form_action_affinity = _b01(form_development.get("symbol_action_affinity", form_state.get("form_symbol_action_trust", 0.0)))
    form_learning_trust = _b01(form_state.get("form_symbol_learning_trust", 0.0))
    form_novelty = _b01(form_state.get("form_symbol_novelty", 0.0))

    process_core = _b01(
        (perception_quality * 0.16)
        + (felt_quality * 0.14)
        + (thought_quality * 0.16)
        + (plan_quality * 0.22)
        + (execution_quality * 0.17)
        + (risk_fit_quality * 0.15),
        default=0.50,
    )
    packet_bearing_quality = _b01(
        (structure_quality * 0.24)
        + (structure_action_bearing * 0.16)
        + (field_action_support * 0.14)
        + (transfer_bearing * 0.12)
        + (interpretation_quality * 0.12)
        + (context_quality * 0.10)
        + (load_bearing_capacity * 0.08)
        + (form_structural_support * 0.04)
    )
    packet_inner_outer_fit = _b01(
        (inner_outer_alignment * 0.26)
        + (perceptual_distance * 0.14)
        + (release_capacity * 0.12)
        + ((1.0 - field_attachment) * 0.12)
        + (emotional_decoupling * 0.10)
        + (felt_quality * 0.10)
        + (thought_quality * 0.08)
        + (experience_regulation * 0.05)
        + ((1.0 - diffuse_open_development_pressure) * 0.03)
    )
    packet_confidence_integrity = _b01(
        (action_clearance * 0.19)
        + (regulated_courage * 0.18)
        + (plan_quality * 0.18)
        + (risk_fit_quality * 0.16)
        + (packet_bearing_quality * 0.15)
        + (execution_quality * 0.10)
        - (max(0.0, action_clearance - packet_bearing_quality) * 0.12)
        - (action_inhibition * 0.06)
    )
    packet_repetition_potential = _b01(
        (process_core * 0.20)
        + (packet_bearing_quality * 0.20)
        + (form_process_quality * 0.14)
        + (form_action_affinity * 0.12)
        + (form_learning_trust * 0.10)
        + (context_quality * 0.10)
        + (packet_confidence_integrity * 0.08)
        - (risk_width_pressure * 0.08)
        - (overtrade_pressure * 0.06)
    )
    packet_curiosity_pull = _b01(
        (curiosity_tone * 0.22)
        + (object_contact_depth * 0.18)
        + (selective_attention * 0.16)
        + (form_novelty * 0.14)
        + (packet_repetition_potential * 0.12)
        + (max(0.0, 0.62 - packet_bearing_quality) * 0.08)
        - (fatigue_tone * 0.10)
    )

    outcome_confirmation = 0.0
    if reason == "tp_hit":
        outcome_confirmation = 0.10
    elif reason == "sl_hit":
        outcome_confirmation = -0.07
    elif reason in ("cancel", "timeout"):
        outcome_confirmation = -0.03
    elif reason in ("reward_too_small", "rr_too_low", "sl_distance_too_high"):
        outcome_confirmation = -0.05

    packet_process_reward = _b01(
        (process_core * 0.34)
        + (packet_bearing_quality * 0.22)
        + (packet_inner_outer_fit * 0.18)
        + (packet_confidence_integrity * 0.12)
        + (packet_repetition_potential * 0.10)
        + outcome_confirmation
        - (overtrade_pressure * 0.07)
        - (risk_width_pressure * 0.06)
    )
    packet_reorganization_need = _b01(
        ((1.0 - process_core) * 0.22)
        + ((1.0 - packet_bearing_quality) * 0.20)
        + ((1.0 - packet_inner_outer_fit) * 0.16)
        + (risk_width_pressure * 0.12)
        + (overtrade_pressure * 0.10)
        + (diffuse_open_development_pressure * 0.10)
        + (attempt_density * 0.06)
        + (0.06 if reason == "sl_hit" else 0.0)
        - (packet_process_reward * 0.16)
    )
    constructive_stimulation = _b01(
        (packet_process_reward * 0.42)
        + (packet_repetition_potential * 0.20)
        + (packet_inner_outer_fit * 0.16)
        + (packet_curiosity_pull * 0.12)
        + (max(0.0, outcome_confirmation) * 0.10)
        - (packet_reorganization_need * 0.10)
    )
    constructive_dopamine = _b01(
        (packet_process_reward * 0.34)
        + (packet_repetition_potential * 0.28)
        + (packet_curiosity_pull * 0.22)
        + (max(0.0, outcome_confirmation) * 0.08)
    )
    stabilizing_serotonin = _b01(
        (packet_inner_outer_fit * 0.30)
        + (packet_bearing_quality * 0.26)
        + (packet_confidence_integrity * 0.16)
        + (release_capacity * 0.12)
        + (reflection_maturity * 0.08)
        - (packet_reorganization_need * 0.10)
    )
    relief_endorphin = _b01(
        (packet_process_reward * 0.24)
        + (pressure_release * 0.24)
        + (release_capacity * 0.18)
        + ((1.0 - risk_width_pressure) * 0.10)
        + (packet_inner_outer_fit * 0.08)
        - (fatigue_tone * 0.08)
    )
    focused_acetylcholine = _b01(
        (perception_quality * 0.20)
        + (object_contact_depth * 0.18)
        + (selective_attention * 0.16)
        + (packet_curiosity_pull * 0.16)
        + (packet_repetition_potential * 0.14)
        + ((1.0 - diffuse_open_development_pressure) * 0.08)
    )

    if (
        (packet_process_reward >= 0.52 and packet_reorganization_need < 0.36)
        or (
            packet_process_reward >= 0.46
            and packet_bearing_quality >= 0.42
            and packet_inner_outer_fit >= 0.38
            and packet_reorganization_need < 0.42
        )
    ):
        packet_label = "constructive_packet"
    elif packet_reorganization_need >= 0.58 or (packet_process_reward < 0.34 and packet_reorganization_need >= 0.43):
        packet_label = "reorganize_packet"
    elif (
        packet_bearing_quality >= 0.50
        and packet_process_reward >= 0.38
        and packet_reorganization_need < 0.48
    ) or (
        packet_bearing_quality >= 0.46
        and packet_process_reward >= 0.40
        and packet_reorganization_need < 0.44
    ):
        packet_label = "bearing_packet"
    elif packet_curiosity_pull >= 0.46:
        packet_label = "curiosity_packet"
    elif packet_reorganization_need >= 0.50 and packet_process_reward < 0.34:
        packet_label = "reorganize_packet"
    else:
        packet_label = "mixed_packet"

    return {
        "experience_packet_label": str(packet_label),
        "packet_bearing_quality": float(packet_bearing_quality),
        "packet_inner_outer_fit": float(packet_inner_outer_fit),
        "packet_confidence_integrity": float(packet_confidence_integrity),
        "packet_repetition_potential": float(packet_repetition_potential),
        "packet_curiosity_pull": float(packet_curiosity_pull),
        "packet_process_reward": float(packet_process_reward),
        "packet_reorganization_need": float(packet_reorganization_need),
        "constructive_stimulation": float(constructive_stimulation),
        "constructive_dopamine": float(constructive_dopamine),
        "stabilizing_serotonin": float(stabilizing_serotonin),
        "relief_endorphin": float(relief_endorphin),
        "focused_acetylcholine": float(focused_acetylcholine),
    }

# --------------------------------------------------
def build_temporal_coherence_state(
    temporal_perception_state=None,
    bot=None,
    visual_market_state=None,
    structure_perception_state=None,
    form_symbol_state=None,
    state_signature=None,
    candle_state=None,
):

    previous = dict(temporal_perception_state or {})
    visual = dict(visual_market_state or {})
    structure = dict(structure_perception_state or {})
    symbol = dict(form_symbol_state or {})
    signature = dict(state_signature or {})
    candle = dict(candle_state or {})

    def _clip(value, lo=0.0, hi=1.0):
        try:
            value = float(value)
        except Exception:
            value = 0.0
        if value != value:
            value = 0.0
        return max(float(lo), min(float(hi), float(value)))

    def _flt(value, default=0.0):
        try:
            return float(value)
        except Exception:
            return float(default)

    runtime_tick = int(getattr(bot, "mcm_runtime_market_ticks", 0) or 0) if bot is not None else 0
    timestamp = candle.get("timestamp", None)
    visual_form = dict(visual.get("visual_form_state", {}) or {})
    form_symbol_id = str(symbol.get("form_symbol_id", "") or "").strip()
    form_symbol_family_key = str(symbol.get("form_symbol_family_key", symbol.get("form_symbol_key", "")) or "").strip()
    form_symbol_variant_key = str(symbol.get("form_symbol_variant_key", "") or "").strip()
    compound_id = str(symbol.get("form_symbol_compound_id", "") or "").strip()
    compound_scope = str(symbol.get("form_symbol_compound_scope", "") or "").strip()
    uncertain_form_family_state = str(symbol.get("uncertain_form_family_state", "") or "").strip()
    visual_form_id = str(visual.get("visual_form_id", visual_form.get("visual_form_id", "")) or "").strip()
    signature_key = str(signature.get("signature_key", "") or "").strip()
    context_cluster_id = str(getattr(bot, "last_context_cluster_id", "") or "").strip() if bot is not None else ""
    inner_context_cluster_id = str(getattr(bot, "last_inner_context_cluster_id", "") or "").strip() if bot is not None else ""

    visual_bucket = "|".join(
        str(round(_flt(visual.get(key, 0.0)), 2))
        for key in ("visual_clarity", "visual_object_stability", "visual_shape_resonance", "visual_shape_fragility")
    )
    family_anchor = form_symbol_family_key or form_symbol_id or form_symbol_variant_key
    identity_parts = [
        item
        for item in (
            family_anchor,
            uncertain_form_family_state,
            compound_scope,
            context_cluster_id,
            inner_context_cluster_id,
            visual_bucket,
        )
        if item and item != "-"
    ]
    if identity_parts:
        raw_identity = "|".join(identity_parts[:5])
    else:
        raw_identity = visual_bucket
    source_identity_parts = [
        item
        for item in (
            form_symbol_id,
            compound_id,
            visual_form_id,
            context_cluster_id,
            inner_context_cluster_id,
            signature_key[:16] if signature_key else "",
        )
        if item and item != "-"
    ]
    raw_source_identity = "|".join(source_identity_parts[:6]) if source_identity_parts else raw_identity
    temporal_identity = hashlib.sha1(raw_identity.encode("utf-8", errors="ignore")).hexdigest()[:12] if raw_identity else "-"
    temporal_source_identity = hashlib.sha1(raw_source_identity.encode("utf-8", errors="ignore")).hexdigest()[:12] if raw_source_identity else temporal_identity

    previous_identity = str(previous.get("temporal_identity", "") or "").strip()
    identity_memory = dict(previous.get("temporal_identity_memory", {}) or {})
    remembered = dict(identity_memory.get(temporal_identity, {}) or {}) if temporal_identity and temporal_identity != "-" else {}
    last_seen_tick = int(remembered.get("last_seen_tick", previous.get("last_seen_tick", runtime_tick)) or runtime_tick)
    ticks_since_seen = max(0, int(runtime_tick) - int(last_seen_tick)) if remembered else 999
    previous_timestamp = previous.get("last_timestamp", None)
    same_identity = bool(temporal_identity and temporal_identity != "-" and temporal_identity == previous_identity)

    visual_clarity = _clip(visual.get("visual_clarity", 0.0))
    visual_object_stability = _clip(visual.get("visual_object_stability", 0.0))
    visual_grounding_strength = _clip(visual.get("visual_grounding_strength", visual.get("visual_object_binding", 0.0)))
    visual_form_novelty = _clip(visual.get("visual_form_novelty", 0.0))
    visual_shape_resonance = _clip(visual.get("visual_shape_resonance", 0.0))
    visual_shape_fragility = _clip(visual.get("visual_shape_fragility", 0.0))
    structure_quality = _clip(structure.get("structure_quality", 0.0))
    structure_stability = _clip(structure.get("structure_stability", 0.0))
    context_confidence = _clip(structure.get("context_confidence", 0.0))
    route_familiarity = _clip(previous.get("route_familiarity", 0.0))
    symbol_learning_trust = _clip(symbol.get("form_symbol_learning_trust", 0.0))
    symbol_action_trust = _clip(symbol.get("form_symbol_action_trust", 0.0))
    symbol_caution_trust = _clip(symbol.get("form_symbol_caution_trust", 0.0))

    previous_continuity = _clip(previous.get("temporal_continuity", 0.0))
    previous_afterimage = _clip(previous.get("temporal_afterimage", 0.0))
    previous_source_binding = _clip(previous.get("temporal_source_binding", 0.0))
    previous_self_consistency = _clip(previous.get("temporal_self_consistency", 0.0))

    recurrence_raw = 0.0
    if remembered:
        recurrence_raw = _clip((1.0 / (1.0 + (ticks_since_seen / 24.0))) + (_clip(remembered.get("seen_count", 0.0)) * 0.08))
    elif same_identity:
        recurrence_raw = 0.52

    source_binding = _clip(
        (visual_grounding_strength * 0.18)
        + (visual_object_stability * 0.14)
        + (visual_clarity * 0.12)
        + (structure_quality * 0.14)
        + (structure_stability * 0.12)
        + (context_confidence * 0.10)
        + (symbol_learning_trust * 0.08)
        + (max(symbol_action_trust, symbol_caution_trust) * 0.06)
        + (previous_source_binding * 0.06)
    )
    continuity = _clip(
        (previous_continuity * 0.20)
        + ((1.0 if same_identity else 0.0) * 0.22)
        + (recurrence_raw * 0.18)
        + (source_binding * 0.18)
        + (visual_object_stability * 0.10)
        + (structure_stability * 0.08)
        + (max(0.0, 1.0 - visual_form_novelty) * 0.04)
    )
    novelty = _clip(
        (visual_form_novelty * 0.24)
        + (visual_shape_fragility * 0.12)
        + ((0.0 if same_identity else 1.0) * 0.18)
        + (max(0.0, 0.48 - source_binding) * 0.18)
        + (max(0.0, 0.34 - recurrence_raw) * 0.12)
        - (continuity * 0.12)
    )
    afterimage = _clip(
        (previous_afterimage * 0.72)
        + (max(0.0, continuity - source_binding) * 0.12)
        + (visual_shape_resonance * 0.07)
        + (max(0.0, novelty - continuity) * 0.06)
        - (source_binding * 0.05)
    )
    memory_time_distance = _clip(1.0 if not remembered else ticks_since_seen / 96.0)
    temporal_decay = _clip((memory_time_distance * 0.58) + (afterimage * 0.18) + (max(0.0, 0.36 - continuity) * 0.16))
    temporal_context_depth = _clip(
        (continuity * 0.20)
        + (recurrence_raw * 0.16)
        + (source_binding * 0.16)
        + (structure_quality * 0.12)
        + (symbol_learning_trust * 0.10)
        + (visual_shape_resonance * 0.08)
        + (max(0.0, 1.0 - memory_time_distance) * 0.10)
        + (context_confidence * 0.08)
    )
    temporal_self_consistency = _clip(
        (previous_self_consistency * 0.18)
        + (continuity * 0.22)
        + (source_binding * 0.18)
        + (temporal_context_depth * 0.14)
        + (structure_stability * 0.10)
        + (visual_object_stability * 0.08)
        - (novelty * 0.08)
        - (temporal_decay * 0.06)
    )
    perception_sequence_coherence = _clip(
        (continuity * 0.24)
        + (temporal_self_consistency * 0.20)
        + (source_binding * 0.18)
        + (recurrence_raw * 0.12)
        + (max(0.0, 1.0 - temporal_decay) * 0.10)
        + (context_confidence * 0.08)
        - (novelty * 0.08)
    )
    memory_experience_depth = _clip(
        (max(0.0, 1.0 - memory_time_distance) * 0.30)
        + (recurrence_raw * 0.20)
        + (temporal_context_depth * 0.18)
        + (afterimage * 0.14)
        + (source_binding * 0.10)
        + (symbol_learning_trust * 0.08)
    )
    future_projection_depth = _clip(
        (temporal_context_depth * 0.22)
        + (perception_sequence_coherence * 0.18)
        + (structure_stability * 0.14)
        + (context_confidence * 0.12)
        + (max(symbol_action_trust, symbol_caution_trust) * 0.10)
        + (visual_shape_resonance * 0.10)
        + (max(0.0, 1.0 - temporal_decay) * 0.14)
    )
    mcm_spacetime_depth = _clip(
        (temporal_context_depth * 0.24)
        + (source_binding * 0.16)
        + (max(0.0, 1.0 - memory_time_distance) * 0.14)
        + (afterimage * 0.12)
        + (recurrence_raw * 0.12)
        + (visual_shape_resonance * 0.08)
        + (structure_quality * 0.08)
        + (context_confidence * 0.06)
    )
    temporal_self_location = _clip(
        (mcm_spacetime_depth * 0.22)
        + (source_binding * 0.18)
        + (continuity * 0.16)
        + (perception_sequence_coherence * 0.14)
        + (max(0.0, 1.0 - temporal_decay) * 0.12)
        + (max(0.0, 1.0 - novelty) * 0.08)
        + (previous_self_consistency * 0.10)
    )

    if novelty >= 0.54 and continuity < 0.28 and source_binding < 0.42:
        temporal_binding_state = "new_contact"
    elif continuity >= 0.42 and memory_time_distance < 0.30:
        temporal_binding_state = "continued_contact"
    elif recurrence_raw >= 0.28 and memory_time_distance >= 0.18:
        temporal_binding_state = "recurrent_contact"
    elif afterimage >= 0.28 and source_binding < 0.40 and temporal_decay >= 0.36:
        temporal_binding_state = "afterimage_contact"
    elif perception_sequence_coherence >= 0.38 and source_binding >= 0.34:
        temporal_binding_state = "coherent_sequence"
    elif memory_time_distance >= 0.62 and continuity < 0.26 and source_binding < 0.42:
        temporal_binding_state = "aged_memory_contact"
    else:
        temporal_binding_state = "unbound_moment"

    temporal_self_location_state = "unlocated_contact"
    if temporal_binding_state in ("continued_contact", "coherent_sequence") and temporal_self_location >= 0.42:
        temporal_self_location_state = "present_contact"
    elif afterimage >= 0.30 and temporal_decay >= 0.34:
        temporal_self_location_state = "afterimage_trace"
    elif memory_experience_depth >= 0.42 and memory_time_distance >= 0.18:
        temporal_self_location_state = "remembered_experience"
    elif future_projection_depth >= 0.42 and temporal_context_depth >= 0.30:
        temporal_self_location_state = "future_possibility"
    elif novelty >= 0.48 and source_binding < 0.38:
        temporal_self_location_state = "new_unmapped_contact"

    spacetime_unlocated_pressure = _clip(
        (max(0.0, 0.34 - temporal_self_location) * 0.56)
        + (max(0.0, 0.30 - mcm_spacetime_depth) * 0.34)
        + ((1.0 if temporal_self_location_state == "unlocated_contact" else 0.0) * 0.16)
        + ((1.0 if temporal_binding_state == "unbound_moment" else 0.0) * 0.10)
        + (novelty * 0.08)
        - (source_binding * 0.10)
    )
    spacetime_memory_bearing = _clip(
        (memory_experience_depth * 0.30)
        + (recurrence_raw * 0.16)
        + (temporal_context_depth * 0.16)
        + (temporal_self_location * 0.14)
        + (perception_sequence_coherence * 0.12)
        + (max(0.0, 1.0 - memory_time_distance) * 0.12)
    )
    spacetime_future_bearing = _clip(
        (future_projection_depth * 0.34)
        + (mcm_spacetime_depth * 0.20)
        + (temporal_self_location * 0.16)
        + (perception_sequence_coherence * 0.14)
        + (structure_quality * 0.08)
        + (context_confidence * 0.08)
    )
    spacetime_regulation_support = _clip(
        (spacetime_memory_bearing * 0.30)
        + (spacetime_future_bearing * 0.30)
        + (temporal_self_location * 0.18)
        + (mcm_spacetime_depth * 0.14)
        + (source_binding * 0.08)
        - (spacetime_unlocated_pressure * 0.18)
    )
    spacetime_reflection_need = _clip(
        (spacetime_unlocated_pressure * 0.36)
        + (max(0.0, future_projection_depth - temporal_self_location) * 0.16)
        + (max(0.0, mcm_spacetime_depth - memory_experience_depth) * 0.10)
        + ((1.0 if temporal_self_location_state == "future_possibility" else 0.0) * 0.06)
        + ((1.0 if temporal_self_location_state == "afterimage_trace" else 0.0) * 0.10)
        - (spacetime_memory_bearing * 0.10)
    )
    spacetime_regulation_state = "spacetime_open"
    if spacetime_unlocated_pressure >= 0.34 and spacetime_regulation_support < 0.28:
        spacetime_regulation_state = "spacetime_unlocated_reflection"
    elif temporal_self_location_state == "afterimage_trace" and spacetime_reflection_need >= 0.24:
        spacetime_regulation_state = "afterimage_reframe"
    elif temporal_self_location_state == "remembered_experience" and spacetime_memory_bearing >= 0.34:
        spacetime_regulation_state = "memory_depth_bearing"
    elif temporal_self_location_state == "future_possibility" and spacetime_future_bearing >= 0.38:
        spacetime_regulation_state = "future_depth_watch"
    elif temporal_self_location_state == "present_contact" and spacetime_regulation_support >= 0.34:
        spacetime_regulation_state = "present_depth_bearing"

    identity_memory[temporal_identity] = {
        "last_seen_tick": int(runtime_tick),
        "last_timestamp": timestamp,
        "seen_count": int(remembered.get("seen_count", 0) or 0) + 1,
        "last_continuity": float(continuity),
        "last_source_binding": float(source_binding),
        "last_state": str(temporal_binding_state),
    }
    if len(identity_memory) > 96:
        sorted_items = sorted(
            identity_memory.items(),
            key=lambda kv: int(dict(kv[1] or {}).get("last_seen_tick", 0) or 0),
            reverse=True,
        )
        identity_memory = dict(sorted_items[:96])

    merged = dict(previous or {})
    merged.update({
        "temporal_identity": str(temporal_identity),
        "temporal_identity_source": str(raw_identity),
        "temporal_source_identity": str(temporal_source_identity),
        "temporal_source_identity_detail": str(raw_source_identity),
        "temporal_binding_state": str(temporal_binding_state),
        "temporal_continuity": float(continuity),
        "temporal_source_binding": float(source_binding),
        "temporal_recurrence": float(recurrence_raw),
        "temporal_novelty": float(novelty),
        "temporal_afterimage": float(afterimage),
        "temporal_decay": float(temporal_decay),
        "temporal_context_depth": float(temporal_context_depth),
        "mcm_spacetime_depth": float(mcm_spacetime_depth),
        "memory_experience_depth": float(memory_experience_depth),
        "future_projection_depth": float(future_projection_depth),
        "temporal_self_location": float(temporal_self_location),
        "temporal_self_location_state": str(temporal_self_location_state),
        "spacetime_unlocated_pressure": float(spacetime_unlocated_pressure),
        "spacetime_memory_bearing": float(spacetime_memory_bearing),
        "spacetime_future_bearing": float(spacetime_future_bearing),
        "spacetime_reflection_need": float(spacetime_reflection_need),
        "spacetime_regulation_support": float(spacetime_regulation_support),
        "spacetime_regulation_state": str(spacetime_regulation_state),
        "temporal_self_consistency": float(temporal_self_consistency),
        "perception_sequence_coherence": float(perception_sequence_coherence),
        "memory_time_distance": float(memory_time_distance),
        "temporal_structure_quality": float(structure_quality),
        "temporal_structure_stability": float(structure_stability),
        "temporal_context_confidence": float(context_confidence),
        "temporal_visual_grounding_strength": float(visual_grounding_strength),
        "temporal_ticks_since_seen": int(ticks_since_seen if remembered else 999),
        "temporal_same_identity": bool(same_identity),
        "last_seen_tick": int(runtime_tick),
        "last_timestamp": timestamp,
        "previous_timestamp": previous_timestamp,
        "temporal_identity_memory": dict(identity_memory or {}),
    })
    return dict(merged or {})

# --------------------------------------------------
def _resolve_temporal_decision_modulation(temporal_perception_state=None):

    temporal_state = dict(temporal_perception_state or {})
    flow_direction = float(temporal_state.get("flow_direction", 0.0) or 0.0)
    flow_strength = float(temporal_state.get("flow_strength", 0.0) or 0.0)
    flow_stability = float(temporal_state.get("flow_stability", 0.0) or 0.0)
    acceleration = float(temporal_state.get("acceleration", 0.0) or 0.0)
    swing_pressure = float(temporal_state.get("swing_pressure", 0.0) or 0.0)
    sequence_bias = str(temporal_state.get("sequence_bias", "neutral") or "neutral").strip().lower()
    flow_memory = float(temporal_state.get("flow_memory", 0.0) or 0.0)
    transition_pressure = float(temporal_state.get("transition_pressure", 0.0) or 0.0)
    continuation_readiness = float(temporal_state.get("continuation_readiness", 0.0) or 0.0)
    temporal_exhaustion = float(temporal_state.get("temporal_exhaustion", 0.0) or 0.0)
    temporal_coherence = float(temporal_state.get("temporal_coherence", 0.0) or 0.0)
    state_drift = float(temporal_state.get("state_drift", 0.0) or 0.0)

    directional_bias = float(((flow_direction * 0.16) + (flow_memory * 0.14)) * (1.0 + (flow_strength * 0.18) + (flow_stability * 0.12)))
    conviction_boost = float((max(0.0, flow_strength) * 0.08) + (max(0.0, flow_stability) * 0.06) + (continuation_readiness * 0.10) + (temporal_coherence * 0.08))
    caution_penalty = float((max(0.0, swing_pressure) * 0.08) + (max(0.0, 1.0 - flow_stability) * 0.05) + (transition_pressure * 0.10) + (temporal_exhaustion * 0.10))
    continuation_bias = float((max(0.0, flow_strength) * max(0.0, flow_stability) * 0.08) + (continuation_readiness * 0.12) + (max(0.0, temporal_coherence - transition_pressure) * 0.10))
    exhaustion_risk = float(min(0.28, (max(0.0, abs(acceleration)) * 0.12) + (max(0.0, swing_pressure - flow_stability) * 0.10) + (temporal_exhaustion * 0.14) + (state_drift * 0.10)))
    observe_pull = float((max(0.0, 1.0 - flow_stability) * 0.18) + (max(0.0, swing_pressure) * 0.12) + (transition_pressure * 0.18) + (temporal_exhaustion * 0.14))
    replan_pull = float((max(0.0, swing_pressure) * 0.16) + (max(0.0, abs(acceleration)) * 0.10) + (transition_pressure * 0.20) + (state_drift * 0.14))

    if sequence_bias == "up":
        long_bias = directional_bias + continuation_bias
        short_bias = -max(0.0, directional_bias * 0.42)
    elif sequence_bias == "down":
        long_bias = -max(0.0, (-directional_bias) * 0.42)
        short_bias = -directional_bias + continuation_bias
    else:
        long_bias = directional_bias * 0.42
        short_bias = -directional_bias * 0.42
        observe_pull += 0.06

    return {
        "flow_direction": float(flow_direction),
        "flow_strength": float(flow_strength),
        "flow_stability": float(flow_stability),
        "acceleration": float(acceleration),
        "swing_pressure": float(swing_pressure),
        "sequence_bias": str(sequence_bias),
        "flow_memory": float(flow_memory),
        "transition_pressure": float(transition_pressure),
        "continuation_readiness": float(continuation_readiness),
        "temporal_exhaustion": float(temporal_exhaustion),
        "temporal_coherence": float(temporal_coherence),
        "state_drift": float(state_drift),
        "long_bias": float(long_bias),
        "short_bias": float(short_bias),
        "conviction_boost": float(conviction_boost),
        "caution_penalty": float(caution_penalty),
        "continuation_bias": float(continuation_bias),
        "exhaustion_risk": float(exhaustion_risk),
        "observe_pull": float(observe_pull),
        "replan_pull": float(replan_pull),
    }

# --------------------------------------------------
def _advance_temporal_perception_state(temporal_perception_state=None, bot=None, decision_tendency="hold", market_tick_advanced=True):

    temporal_state = dict(temporal_perception_state or {})
    if not temporal_state:
        return {}

    flow_direction = float(temporal_state.get("flow_direction", 0.0) or 0.0)
    flow_strength = float(temporal_state.get("flow_strength", 0.0) or 0.0)
    flow_stability = float(temporal_state.get("flow_stability", 0.0) or 0.0)
    swing_pressure = float(temporal_state.get("swing_pressure", 0.0) or 0.0)
    flow_memory = float(temporal_state.get("flow_memory", flow_direction) or flow_direction)
    transition_pressure = float(temporal_state.get("transition_pressure", 0.0) or 0.0)
    continuation_readiness = float(temporal_state.get("continuation_readiness", 0.0) or 0.0)
    temporal_exhaustion = float(temporal_state.get("temporal_exhaustion", 0.0) or 0.0)
    temporal_coherence = float(temporal_state.get("temporal_coherence", 0.0) or 0.0)
    state_drift = float(temporal_state.get("state_drift", 0.0) or 0.0)

    inhibition_level = float(getattr(bot, "inhibition_level", 0.0) or 0.0) if bot is not None else 0.0
    competition_bias = abs(float(getattr(bot, "competition_bias", 0.0) or 0.0)) if bot is not None else 0.0
    action_capacity = float(getattr(bot, "action_capacity", 0.0) or 0.0) if bot is not None else 0.0
    regulatory_load = float(getattr(bot, "regulatory_load", 0.0) or 0.0) if bot is not None else 0.0
    recovery_need = float(getattr(bot, "recovery_need", 0.0) or 0.0) if bot is not None else 0.0

    if bool(market_tick_advanced):
        temporal_exhaustion = float(min(1.0, max(0.0, (temporal_exhaustion * 0.84) + (swing_pressure * 0.10) + (competition_bias * 0.06))))
        transition_pressure = float(min(1.0, max(0.0, (transition_pressure * 0.80) + (state_drift * 0.12) + (competition_bias * 0.08))))
    else:
        directional_decay = 0.96 if str(decision_tendency or "hold").strip().lower() == "act" else 0.92
        flow_direction = float(flow_direction * directional_decay)
        flow_strength = float(max(0.0, min(1.0, flow_strength * 0.94)))
        flow_memory = float(max(-1.0, min(1.0, (flow_memory * 0.90) + (flow_direction * 0.10))))
        transition_pressure = float(min(1.0, max(0.0, (transition_pressure * 0.92) + (competition_bias * 0.04) + (inhibition_level * 0.03))))
        temporal_exhaustion = float(min(1.0, max(0.0, (temporal_exhaustion * 0.94) + (max(0.0, regulatory_load - action_capacity) * 0.05) - (max(0.0, action_capacity - regulatory_load) * 0.03))))

    if str(decision_tendency or "hold").strip().lower() in ("observe", "hold"):
        transition_pressure = float(max(0.0, transition_pressure - 0.03))
        temporal_exhaustion = float(max(0.0, temporal_exhaustion - 0.02))
    elif str(decision_tendency or "hold").strip().lower() == "replan":
        transition_pressure = float(min(1.0, transition_pressure + 0.04))
        state_drift = float(min(1.0, state_drift + 0.03))

    continuation_readiness = float(min(1.0, max(0.0, (continuation_readiness * 0.76) + (flow_strength * 0.10) + (flow_stability * 0.08) + (max(0.0, action_capacity - regulatory_load) * 0.10) - (transition_pressure * 0.10) - (temporal_exhaustion * 0.08))))
    temporal_coherence = float(min(1.0, max(0.0, (temporal_coherence * 0.74) + (flow_stability * 0.12) + (continuation_readiness * 0.10) + (max(0.0, 1.0 - transition_pressure) * 0.08) - (recovery_need * 0.06))))

    temporal_state["flow_direction"] = float(flow_direction)
    temporal_state["flow_strength"] = float(flow_strength)
    temporal_state["flow_memory"] = float(flow_memory)
    temporal_state["transition_pressure"] = float(transition_pressure)
    temporal_state["continuation_readiness"] = float(continuation_readiness)
    temporal_state["temporal_exhaustion"] = float(temporal_exhaustion)
    temporal_state["temporal_coherence"] = float(temporal_coherence)
    temporal_state["state_drift"] = float(state_drift)
    return dict(temporal_state)

# --------------------------------------------------
def _advance_felt_state(felt_state=None, bot=None, decision_tendency="hold", market_tick_advanced=True):

    state = dict(felt_state or {})
    if not state:
        return {}

    previous_state = dict(getattr(bot, "felt_state", {}) or {}) if bot is not None else {}

    felt_pressure = float(state.get("felt_pressure", 0.0) or 0.0)
    felt_stability = float(state.get("felt_stability", 0.0) or 0.0)
    felt_alignment = float(state.get("felt_alignment", 0.0) or 0.0)
    felt_conflict = float(state.get("felt_conflict", 0.0) or 0.0)
    felt_risk = float(state.get("felt_risk", 0.0) or 0.0)
    felt_opportunity = float(state.get("felt_opportunity", 0.0) or 0.0)

    previous_pressure = float(previous_state.get("felt_pressure", felt_pressure) or felt_pressure)
    previous_stability = float(previous_state.get("felt_stability", felt_stability) or felt_stability)
    previous_alignment = float(previous_state.get("felt_alignment", felt_alignment) or felt_alignment)
    previous_conflict = float(previous_state.get("felt_conflict", felt_conflict) or felt_conflict)
    previous_risk = float(previous_state.get("felt_risk", felt_risk) or felt_risk)
    previous_opportunity = float(previous_state.get("felt_opportunity", felt_opportunity) or felt_opportunity)
    previous_carry = float(previous_state.get("felt_carry", 0.0) or 0.0)
    previous_residue = float(previous_state.get("felt_residue", 0.0) or 0.0)
    previous_settlement = float(previous_state.get("felt_settlement", 0.0) or 0.0)
    previous_drift = float(previous_state.get("felt_drift", 0.0) or 0.0)

    regulatory_load = float(getattr(bot, "regulatory_load", 0.0) or 0.0) if bot is not None else 0.0
    action_capacity = float(getattr(bot, "action_capacity", 0.0) or 0.0) if bot is not None else 0.0
    recovery_need = float(getattr(bot, "recovery_need", 0.0) or 0.0) if bot is not None else 0.0
    competition_bias = abs(float(getattr(bot, "competition_bias", 0.0) or 0.0)) if bot is not None else 0.0

    felt_pressure = float(min(1.0, max(0.0, (previous_pressure * 0.28) + (felt_pressure * 0.72))))
    felt_stability = float(min(1.0, max(0.0, (previous_stability * 0.26) + (felt_stability * 0.74))))
    felt_alignment = float(min(1.0, max(0.0, (previous_alignment * 0.30) + (felt_alignment * 0.70))))
    felt_conflict = float(min(1.0, max(0.0, (previous_conflict * 0.34) + (felt_conflict * 0.66))))
    felt_risk = float(min(1.0, max(0.0, (previous_risk * 0.30) + (felt_risk * 0.70))))
    felt_opportunity = float(min(1.0, max(0.0, (previous_opportunity * 0.30) + (felt_opportunity * 0.70))))

    felt_drift = float(min(1.0, max(0.0, (abs(felt_pressure - previous_pressure) * 0.34) + (abs(felt_conflict - previous_conflict) * 0.26) + (abs(felt_alignment - previous_alignment) * 0.18) + (competition_bias * 0.12) + (max(0.0, regulatory_load - action_capacity) * 0.10))))
    felt_carry = float(min(1.0, max(0.0, (previous_carry * 0.62) + (felt_pressure * 0.18) + (felt_conflict * 0.14) + (felt_risk * 0.10) - (felt_stability * 0.10) - (felt_alignment * 0.08))))
    felt_residue = float(min(1.0, max(0.0, (previous_residue * 0.66) + (max(0.0, regulatory_load - action_capacity) * 0.16) + (recovery_need * 0.12) + (felt_carry * 0.10) - (max(0.0, action_capacity - regulatory_load) * 0.08))))
    felt_settlement = float(previous_settlement)

    if bool(market_tick_advanced):
        felt_settlement = float(min(1.0, max(0.0, (previous_settlement * 0.54) + (felt_stability * 0.18) + (felt_alignment * 0.14) - (felt_pressure * 0.10) - (felt_conflict * 0.08))))
    else:
        felt_pressure = float(min(1.0, max(0.0, (felt_pressure * 0.94) + (felt_carry * 0.05) - (felt_settlement * 0.04))))
        felt_conflict = float(min(1.0, max(0.0, (felt_conflict * 0.94) + (felt_residue * 0.04) - (felt_settlement * 0.03))))
        felt_stability = float(min(1.0, max(0.0, (felt_stability * 0.96) + (felt_settlement * 0.04) - (felt_residue * 0.03))))
        felt_alignment = float(min(1.0, max(0.0, (felt_alignment * 0.96) + (felt_settlement * 0.04) - (felt_drift * 0.03))))
        felt_settlement = float(min(1.0, max(0.0, (previous_settlement * 0.72) + (felt_stability * 0.10) + (felt_alignment * 0.08) - (felt_residue * 0.06))))

    tendency = str(decision_tendency or "hold").strip().lower()
    if tendency in ("observe", "hold"):
        felt_pressure = float(max(0.0, felt_pressure - 0.03))
        felt_conflict = float(max(0.0, felt_conflict - 0.02))
        felt_settlement = float(min(1.0, felt_settlement + 0.04))
    elif tendency == "replan":
        felt_drift = float(min(1.0, felt_drift + 0.04))
        felt_conflict = float(min(1.0, felt_conflict + 0.02))
    elif tendency == "act":
        felt_pressure = float(min(1.0, felt_pressure + 0.02))
        felt_carry = float(min(1.0, felt_carry + 0.02))

    state["felt_pressure"] = float(felt_pressure)
    state["felt_stability"] = float(felt_stability)
    state["felt_alignment"] = float(felt_alignment)
    state["felt_conflict"] = float(felt_conflict)
    state["felt_risk"] = float(felt_risk)
    state["felt_opportunity"] = float(felt_opportunity)
    state["felt_carry"] = float(felt_carry)
    state["felt_residue"] = float(felt_residue)
    state["felt_settlement"] = float(felt_settlement)
    state["felt_drift"] = float(felt_drift)
    return dict(state)

# --------------------------------------------------
def _advance_thought_state(thought_state=None, felt_state=None, temporal_perception_state=None, bot=None, decision_tendency="hold", market_tick_advanced=True):

    state = dict(thought_state or {})
    if not state:
        return {}

    previous_state = dict(getattr(bot, "thought_state", {}) or {}) if bot is not None else {}
    felt = dict(felt_state or {})
    temporal_state = dict(temporal_perception_state or {})

    decision_conflict = float(state.get("decision_conflict", 0.0) or 0.0)
    state_maturity = float(state.get("state_maturity", 0.0) or 0.0)
    rumination_depth = float(state.get("rumination_depth", 0.0) or 0.0)
    inner_time_scale = float(state.get("inner_time_scale", 0.0) or 0.0)
    decision_readiness = float(state.get("decision_readiness", 0.0) or 0.0)
    thought_alignment = float(state.get("thought_alignment", 0.0) or 0.0)
    decision_pressure = float(state.get("decision_pressure", 0.0) or 0.0)

    previous_conflict = float(previous_state.get("decision_conflict", decision_conflict) or decision_conflict)
    previous_maturity = float(previous_state.get("state_maturity", state_maturity) or state_maturity)
    previous_rumination = float(previous_state.get("rumination_depth", rumination_depth) or rumination_depth)
    previous_time_scale = float(previous_state.get("inner_time_scale", inner_time_scale) or inner_time_scale)
    previous_readiness = float(previous_state.get("decision_readiness", decision_readiness) or decision_readiness)
    previous_alignment = float(previous_state.get("thought_alignment", thought_alignment) or thought_alignment)
    previous_pressure = float(previous_state.get("decision_pressure", decision_pressure) or decision_pressure)
    previous_inertia = float(previous_state.get("thought_inertia", 0.0) or 0.0)
    previous_settlement = float(previous_state.get("thought_settlement", 0.0) or 0.0)
    previous_drift = float(previous_state.get("thought_drift", 0.0) or 0.0)

    felt_pressure = float(felt.get("felt_pressure", 0.0) or 0.0)
    felt_conflict = float(felt.get("felt_conflict", 0.0) or 0.0)
    felt_alignment = float(felt.get("felt_alignment", 0.0) or 0.0)
    felt_stability = float(felt.get("felt_stability", 0.0) or 0.0)
    temporal_transition_pressure = float(temporal_state.get("transition_pressure", 0.0) or 0.0)
    temporal_continuation_readiness = float(temporal_state.get("continuation_readiness", 0.0) or 0.0)
    temporal_exhaustion = float(temporal_state.get("temporal_exhaustion", 0.0) or 0.0)
    temporal_coherence = float(temporal_state.get("temporal_coherence", 0.0) or 0.0)

    decision_conflict = float(min(1.0, max(0.0, (previous_conflict * 0.30) + (decision_conflict * 0.70))))
    state_maturity = float(min(1.0, max(0.0, (previous_maturity * 0.34) + (state_maturity * 0.66))))
    rumination_depth = float(min(1.0, max(0.0, (previous_rumination * 0.32) + (rumination_depth * 0.68))))
    inner_time_scale = float(min(1.0, max(0.0, (previous_time_scale * 0.38) + (inner_time_scale * 0.62))))
    decision_readiness = float(min(1.0, max(0.0, (previous_readiness * 0.30) + (decision_readiness * 0.70))))
    thought_alignment = float(min(1.0, max(0.0, (previous_alignment * 0.32) + (thought_alignment * 0.68))))
    decision_pressure = float(min(1.0, max(0.0, (previous_pressure * 0.28) + (decision_pressure * 0.72))))

    thought_drift = float(min(1.0, max(0.0, (abs(decision_conflict - previous_conflict) * 0.32) + (abs(decision_readiness - previous_readiness) * 0.24) + (temporal_transition_pressure * 0.18) + (felt_conflict * 0.16) + (max(0.0, 1.0 - thought_alignment) * 0.10))))
    thought_inertia = float(min(1.0, max(0.0, (previous_inertia * 0.64) + (rumination_depth * 0.20) + (decision_pressure * 0.12) + (felt_pressure * 0.08) - (state_maturity * 0.08) - (temporal_coherence * 0.06))))
    thought_settlement = float(previous_settlement)

    if bool(market_tick_advanced):
        thought_settlement = float(min(1.0, max(0.0, (previous_settlement * 0.56) + (state_maturity * 0.16) + (thought_alignment * 0.16) + (temporal_coherence * 0.10) - (decision_conflict * 0.08) - (rumination_depth * 0.06))))
    else:
        rumination_depth = float(min(1.0, max(0.0, (rumination_depth * 0.95) + (thought_inertia * 0.05) - (thought_settlement * 0.04))))
        decision_pressure = float(min(1.0, max(0.0, (decision_pressure * 0.94) + (felt_pressure * 0.04) + (temporal_exhaustion * 0.03) - (thought_settlement * 0.04))))
        decision_readiness = float(min(1.0, max(0.0, (decision_readiness * 0.96) + (temporal_continuation_readiness * 0.04) - (thought_inertia * 0.04))))
        thought_alignment = float(min(1.0, max(0.0, (thought_alignment * 0.96) + (felt_alignment * 0.04) - (thought_drift * 0.03))))
        state_maturity = float(min(1.0, max(0.0, (state_maturity * 0.96) + (felt_stability * 0.04) - (temporal_exhaustion * 0.03))))
        thought_settlement = float(min(1.0, max(0.0, (previous_settlement * 0.74) + (state_maturity * 0.10) + (thought_alignment * 0.08) - (thought_inertia * 0.06))))

    tendency = str(decision_tendency or "hold").strip().lower()
    if tendency in ("observe", "hold"):
        rumination_depth = float(max(0.0, rumination_depth - 0.03))
        decision_pressure = float(max(0.0, decision_pressure - 0.02))
        thought_settlement = float(min(1.0, thought_settlement + 0.04))
    elif tendency == "replan":
        rumination_depth = float(min(1.0, rumination_depth + 0.04))
        thought_drift = float(min(1.0, thought_drift + 0.04))
    elif tendency == "act":
        decision_readiness = float(min(1.0, decision_readiness + 0.03))
        thought_inertia = float(max(0.0, thought_inertia - 0.02))

    state["decision_conflict"] = float(decision_conflict)
    state["state_maturity"] = float(state_maturity)
    state["rumination_depth"] = float(rumination_depth)
    state["inner_time_scale"] = float(inner_time_scale)
    state["decision_readiness"] = float(decision_readiness)
    state["thought_alignment"] = float(thought_alignment)
    state["decision_pressure"] = float(decision_pressure)
    state["thought_inertia"] = float(thought_inertia)
    state["thought_settlement"] = float(thought_settlement)
    state["thought_drift"] = float(thought_drift)
    state["maturity"] = float(state_maturity)
    state["readiness"] = float(decision_readiness)
    state["conflict"] = float(decision_conflict)
    return dict(state)
# --------------------------------------------------
# PRICE BUILD
# --------------------------------------------------
def derive_trade_plan_from_brain(
    side,
    candle_state,
    fused,
    stimulus,
    snapshot,
    bot=None,
    strategic_window_state=None,
    form_symbol_state=None,
):

    decision = str(side or "").upper().strip()
    if decision not in ("LONG", "SHORT"):
        return None

    candle = dict(candle_state or {})
    fused_state = dict(fused or {})
    stimulus_state = dict(stimulus or {})
    snapshot_state = dict(snapshot or {})

    open_price = float(candle.get("open", 0.0) or 0.0)
    high_price = float(candle.get("high", open_price) or open_price)
    low_price = float(candle.get("low", open_price) or open_price)
    close_price = float(candle.get("close", open_price) or open_price)

    if close_price <= 0.0:
        return None

    candle_span = max(high_price - low_price, close_price * 0.0005, 1e-9)
    base_move = max(candle_span, close_price * 0.0012)

    focus = dict(stimulus_state.get("focus", {}) or {})
    filtered_vision = dict(stimulus_state.get("filtered_vision", {}) or {})

    focus_direction = float(focus.get("focus_direction", 0.0) or 0.0)
    focus_confidence = float(focus.get("focus_confidence", 0.0) or 0.0)
    target_lock = float(focus.get("target_lock", 0.0) or 0.0)
    signal_relevance = float(focus.get("signal_relevance", 0.0) or 0.0)
    noise_damp = float(focus.get("noise_damp", 0.0) or 0.0)

    filtered_target_map = float(filtered_vision.get("target_map", 0.0) or 0.0)
    filtered_threat_map = float(filtered_vision.get("threat_map", 0.0) or 0.0)
    filtered_optic_flow = float(filtered_vision.get("optic_flow", 0.0) or 0.0)

    target_drift = float(getattr(bot, "target_drift", 0.0) or 0.0) if bot is not None else 0.0
    load_bearing_capacity = float(getattr(bot, "load_bearing_capacity", 0.0) or 0.0) if bot is not None else 0.0
    protective_width_regulation = float(getattr(bot, "protective_width_regulation", 0.0) or 0.0) if bot is not None else 0.0
    protective_courage = float(getattr(bot, "protective_courage", 0.0) or 0.0) if bot is not None else 0.0
    inhibition_level = float(fused_state.get("inhibition_level", 0.0) or 0.0)
    habituation_level = float(fused_state.get("habituation_level", 0.0) or 0.0)
    competition_bias = float(fused_state.get("competition_bias", 0.0) or 0.0)
    context_cluster_bias = float(fused_state.get("context_cluster_bias", 0.0) or 0.0)
    context_cluster_quality = float(fused_state.get("context_cluster_quality", 0.0) or 0.0)
    signature_bias = float(fused_state.get("signature_bias", 0.0) or 0.0)
    signature_quality = float(fused_state.get("signature_quality", 0.0) or 0.0)
    long_score = float(fused_state.get("long_score", 0.0) or 0.0)
    short_score = float(fused_state.get("short_score", 0.0) or 0.0)
    self_state = str(snapshot_state.get("self_state", "stable") or "stable")

    affective = _resolve_affective_context_modulation(
        bot=bot,
        fused_state=dict(fused_state or {}),
    )
    felt_bearing_score = float(affective.get("felt_bearing_score", 0.0) or 0.0)
    felt_profile_label = str(affective.get("felt_profile_label", "mixed_unclear") or "mixed_unclear")
    conviction_boost = float(affective.get("conviction_boost", 0.0) or 0.0)
    caution_penalty = float(affective.get("caution_penalty", 0.0) or 0.0)
    volatility_penalty = float(affective.get("volatility_penalty", 0.0) or 0.0)
    risk_shift = float(affective.get("risk_shift", 0.0) or 0.0)
    rr_shift = float(affective.get("rr_shift", 0.0) or 0.0)
    width_shift = float(affective.get("width_shift", 0.0) or 0.0)

    directional_score = long_score if decision == "LONG" else short_score
    directional_competition = max(0.0, competition_bias) if decision == "LONG" else max(0.0, -competition_bias)
    entry_pull = max(0.0, abs(target_drift)) * 0.35 + max(0.0, abs(focus_direction)) * 0.18 + max(0.0, filtered_optic_flow) * 0.08
    entry_shift = min(base_move * 0.55, base_move * entry_pull)

    if decision == "LONG":
        entry_price = close_price - entry_shift
        validity_center = entry_price + min(entry_shift * 0.35, base_move * 0.15)
    else:
        entry_price = close_price + entry_shift
        validity_center = entry_price - min(entry_shift * 0.35, base_move * 0.15)

    impulse_entry_price = float(entry_price)
    strategic_entry_price = float(entry_price)
    strategic_entry_weight = 0.0
    strategic_entry_fit = 0.0
    area_motor_intention = 0.0
    area_motor_distance_fit = 0.0
    impulse_entry_intention = 0.0
    area_entry_intention = 0.0
    entry_choice_conflict = 0.0
    entry_choice_bearing = 0.0
    area_direct_readiness = 0.0
    area_motor_restraint = 0.0
    entry_choice_state = "impulse_only"
    strategic_entry_mode = "impulse_contact"
    strategic_area_focus_id = "-"
    strategic_area_low = 0.0
    strategic_area_high = 0.0

    strategic_window = dict(strategic_window_state or {})
    if not strategic_window and bot is not None:
        strategic_window = dict(getattr(bot, "strategic_window_state", {}) or {})
    form_symbol = dict(form_symbol_state or {})
    if not form_symbol and bot is not None:
        form_symbol = dict(getattr(bot, "form_symbol_state", {}) or {})

    def _clip(value, lo=0.0, hi=1.0):
        try:
            value = float(value)
        except Exception:
            value = 0.0
        if value != value:
            value = 0.0
        return max(float(lo), min(float(hi), float(value)))

    selected_strategic_area = dict(strategic_window or {})
    candidate_pool = list(strategic_window.get("area_focus_candidates", []) or []) if isinstance(strategic_window.get("area_focus_candidates", []), list) else []
    if candidate_pool:
        best_area = dict(selected_strategic_area or {})
        best_area_score = -1.0
        for raw_candidate in candidate_pool:
            candidate = dict(raw_candidate or {})
            cand_low = float(candidate.get("area_price_low", 0.0) or 0.0)
            cand_high = float(candidate.get("area_price_high", 0.0) or 0.0)
            if cand_low <= 0.0 or cand_high <= 0.0 or cand_high < cand_low:
                continue
            cand_mid = float(candidate.get("area_price_mid", (cand_low + cand_high) * 0.50) or ((cand_low + cand_high) * 0.50))
            cand_span = max(1e-9, cand_high - cand_low)
            cand_contains = bool(cand_low <= close_price <= cand_high)
            if decision == "LONG":
                cand_directional_fit = _clip((close_price - cand_mid) / max(base_move * 3.4, cand_span, 1e-9))
                cand_side_fit = max(cand_directional_fit, 0.34 if cand_contains else 0.0)
            else:
                cand_directional_fit = _clip((cand_mid - close_price) / max(base_move * 3.4, cand_span, 1e-9))
                cand_side_fit = max(cand_directional_fit, 0.34 if cand_contains else 0.0)
            if cand_side_fit <= 0.02:
                continue
            cand_score = _clip(
                (float(candidate.get("area_order_intention", 0.0) or 0.0) * 0.20)
                + (float(candidate.get("area_bearing_quality", 0.0) or 0.0) * 0.18)
                + (float(candidate.get("area_replay_fit", 0.0) or 0.0) * 0.14)
                + (float(candidate.get("area_action_timing_fit", 0.0) or 0.0) * 0.22)
                + (float(candidate.get("area_present_contact", 0.0) or 0.0) * 0.12)
                + (cand_side_fit * 0.18)
                - (float(candidate.get("area_invalidity_pressure", 0.0) or 0.0) * 0.22)
                - (float(candidate.get("area_afterimage", 0.0) or 0.0) * 0.12)
            )
            if cand_score > best_area_score:
                best_area_score = float(cand_score)
                best_area = dict(candidate)
        if best_area_score > 0.0:
            selected_strategic_area = dict(best_area or {})

    area_low = float(selected_strategic_area.get("area_price_low", 0.0) or 0.0)
    area_high = float(selected_strategic_area.get("area_price_high", 0.0) or 0.0)
    if area_low > 0.0 and area_high > 0.0 and area_high >= area_low:
        area_mid = float(selected_strategic_area.get("area_price_mid", (area_low + area_high) * 0.50) or ((area_low + area_high) * 0.50))
        area_span = max(1e-9, area_high - area_low)
        area_order_intention = _clip(selected_strategic_area.get("area_order_intention", 0.0))
        area_bearing_quality = _clip(selected_strategic_area.get("area_bearing_quality", 0.0))
        area_replay_fit = _clip(selected_strategic_area.get("area_replay_fit", 0.0))
        area_patience_quality = _clip(selected_strategic_area.get("area_patience_quality", 0.0))
        area_invalidity_pressure = _clip(selected_strategic_area.get("area_invalidity_pressure", 0.0))
        area_action_timing_fit = _clip(selected_strategic_area.get("area_action_timing_fit", 0.0))
        area_spacetime_fit = _clip(selected_strategic_area.get("area_spacetime_fit", 0.0))
        area_present_contact = _clip(selected_strategic_area.get("area_present_contact", 0.0))
        area_afterimage = _clip(selected_strategic_area.get("area_afterimage", 0.0))
        area_temporal_relevance = _clip(selected_strategic_area.get("area_temporal_relevance", 0.0))
        contact_maturity = _clip(form_symbol.get("form_symbol_contact_maturity", 0.0))
        contact_utility = _clip(form_symbol.get("form_symbol_contact_utility", 0.0))
        contact_burden = _clip(form_symbol.get("form_symbol_contact_burden_evidence", 0.0))
        contact_carefulness = _clip(form_symbol.get("form_symbol_contact_carefulness", 0.0))
        contact_fit = _clip((contact_maturity * 0.28) + (contact_utility * 0.32) + (area_replay_fit * 0.20) + (area_patience_quality * 0.20) - (contact_burden * 0.18))
        area_contains_price = bool(area_low <= close_price <= area_high)
        if decision == "LONG":
            directional_fit = _clip((close_price - area_mid) / max(base_move * 3.4, area_span, 1e-9))
            containment_fit = 0.34 if area_contains_price else 0.0
            side_fit = max(directional_fit, containment_fit)
            if close_price >= area_low:
                strategic_anchor = min(close_price, area_high - area_span * 0.18)
                strategic_anchor = max(area_low + area_span * 0.12, strategic_anchor)
            else:
                strategic_anchor = impulse_entry_price
        else:
            directional_fit = _clip((area_mid - close_price) / max(base_move * 3.4, area_span, 1e-9))
            containment_fit = 0.34 if area_contains_price else 0.0
            side_fit = max(directional_fit, containment_fit)
            if close_price <= area_high:
                strategic_anchor = max(close_price, area_low + area_span * 0.18)
                strategic_anchor = min(area_high - area_span * 0.12, strategic_anchor)
            else:
                strategic_anchor = impulse_entry_price
        anchor_distance = abs(strategic_anchor - close_price)
        anchor_distance_fit = _clip(1.0 - (anchor_distance / max(base_move * 3.8, area_span * 1.6, 1e-9)))
        area_motor_distance_fit = float(anchor_distance_fit)
        area_motor_intention = _clip(
            (area_order_intention * 0.22)
            + (area_bearing_quality * 0.18)
            + (area_action_timing_fit * 0.16)
            + (area_spacetime_fit * 0.12)
            + (area_replay_fit * 0.10)
            + (area_present_contact * 0.08)
            + (contact_fit * 0.10)
            + (side_fit * 0.08)
            + (anchor_distance_fit * 0.06)
            - (area_invalidity_pressure * 0.16)
            - (area_afterimage * 0.08)
        )
        impulse_entry_intention = _clip(
            (abs(focus_direction) * 0.20)
            + (focus_confidence * 0.16)
            + (target_lock * 0.16)
            + (filtered_optic_flow * 0.12)
            + (directional_competition * 0.10)
            + (max(0.0, directional_score) * 0.10)
            + (conviction_boost * 0.10)
            - (caution_penalty * 0.12)
            - (volatility_penalty * 0.08)
        )
        area_entry_intention = _clip(
            (area_motor_intention * 0.34)
            + (area_order_intention * 0.16)
            + (area_bearing_quality * 0.14)
            + (area_spacetime_fit * 0.10)
            + (area_replay_fit * 0.10)
            + (anchor_distance_fit * 0.10)
            + (contact_fit * 0.08)
            - (area_invalidity_pressure * 0.12)
            - (area_afterimage * 0.06)
        )
        entry_choice_conflict = _clip(
            min(impulse_entry_intention, area_entry_intention)
            * (1.0 - min(1.0, abs(impulse_entry_intention - area_entry_intention) * 1.8))
        )
        entry_choice_bearing = _clip(
            (area_entry_intention * 0.28)
            + (area_bearing_quality * 0.18)
            + (area_spacetime_fit * 0.14)
            + (area_motor_distance_fit * 0.12)
            + (contact_fit * 0.12)
            + (area_action_timing_fit * 0.10)
            - (area_invalidity_pressure * 0.14)
            - (area_afterimage * 0.08)
        )
        area_over_impulse = float(area_entry_intention - impulse_entry_intention)
        area_direct_readiness = _clip(
            (area_entry_intention * 0.22)
            + (entry_choice_bearing * 0.20)
            + (contact_fit * 0.18)
            + (area_action_timing_fit * 0.14)
            + (area_spacetime_fit * 0.10)
            + (area_motor_distance_fit * 0.08)
            + (max(0.0, area_over_impulse) * 0.18)
            - (entry_choice_conflict * 0.10)
            - (area_invalidity_pressure * 0.14)
            - (area_afterimage * 0.08)
        )
        area_motor_restraint = _clip(
            (entry_choice_conflict * 0.28)
            + (max(0.0, -area_over_impulse) * 0.22)
            + (contact_carefulness * max(0.0, 0.42 - contact_maturity) * 0.20)
            + (area_invalidity_pressure * 0.16)
            + (area_afterimage * 0.12)
            + (max(0.0, 0.34 - area_direct_readiness) * 0.20)
        )
        if area_entry_intention > (impulse_entry_intention + 0.05) and entry_choice_bearing >= 0.26:
            entry_choice_state = "area_preferred"
        elif entry_choice_conflict >= 0.18 and entry_choice_bearing >= 0.24:
            entry_choice_state = "entry_choice_conflict"
        elif area_entry_intention >= 0.24 and entry_choice_bearing >= 0.22:
            entry_choice_state = "area_available"
        else:
            entry_choice_state = "impulse_preferred"
        strategic_entry_fit = _clip(
            (area_order_intention * 0.24)
            + (area_bearing_quality * 0.22)
            + (area_replay_fit * 0.14)
            + (area_patience_quality * 0.10)
            + (area_action_timing_fit * 0.18)
            + (area_present_contact * 0.10)
            + (area_temporal_relevance * 0.08)
            + (contact_fit * 0.14)
            + (side_fit * 0.14)
            + (anchor_distance_fit * 0.08)
            - (area_invalidity_pressure * 0.22)
            - (area_afterimage * 0.12)
            - (contact_carefulness * max(0.0, 0.38 - contact_maturity) * 0.10)
        )
        if (
            strategic_anchor > 0.0
            and side_fit > 0.02
            and (
                strategic_entry_fit > 0.22
                or area_motor_intention > 0.24
                or entry_choice_state in ("area_preferred", "entry_choice_conflict", "area_available")
            )
        ):
            strategic_entry_weight = min(
                0.58,
                max(
                    0.0,
                    ((strategic_entry_fit - 0.18) * 0.72)
                    + ((area_motor_intention - 0.24) * 0.52),
                    ((area_entry_intention - impulse_entry_intention) * 0.38)
                    + (entry_choice_bearing * 0.22)
                    + (entry_choice_conflict * 0.04)
                    + (area_direct_readiness * 0.18)
                    - (area_motor_restraint * 0.16)
                    - 0.07,
                ),
            )
            if entry_choice_state == "entry_choice_conflict":
                strategic_entry_weight *= 1.0 - min(0.26, area_motor_restraint * 0.42)
            if area_direct_readiness < 0.34:
                strategic_entry_weight *= 0.84 + (area_direct_readiness * 0.32)
            strategic_entry_price = float((impulse_entry_price * (1.0 - strategic_entry_weight)) + (strategic_anchor * strategic_entry_weight))
            entry_price = float(strategic_entry_price)
            if decision == "LONG":
                validity_center = entry_price + min(abs(close_price - entry_price) * 0.28, base_move * 0.18)
            else:
                validity_center = entry_price - min(abs(close_price - entry_price) * 0.28, base_move * 0.18)
            strategic_entry_mode = "area_contact_intention" if strategic_entry_weight < 0.44 or area_direct_readiness < 0.36 else "area_contact_entry"
            strategic_area_focus_id = str(selected_strategic_area.get("area_focus_id", "-") or "-")
            strategic_area_low = float(area_low)
            strategic_area_high = float(area_high)

    validity_halfwidth = max(
        base_move * 0.20,
        base_move * (
            0.22
            + (1.0 - focus_confidence) * 0.20
            + noise_damp * 0.08
            + inhibition_level * 0.10
            + max(0.0, width_shift)
        ),
    )

    risk_model_score = max(
        0.0,
        min(
            1.0,
            (filtered_threat_map * 0.28)
            + (noise_damp * 0.18)
            + (inhibition_level * 0.18)
            + (habituation_level * 0.10)
            + max(0.0, -context_cluster_bias) * 0.10
            + max(0.0, -signature_bias) * 0.08
            + max(0.0, abs(target_drift)) * 0.10
            + caution_penalty * 0.22
            + volatility_penalty * 0.18,
        ),
    )

    reward_model_score = max(
        0.0,
        min(
            1.0,
            (signal_relevance * 0.24)
            + (target_lock * 0.22)
            + (focus_confidence * 0.18)
            + (filtered_target_map * 0.14)
            + directional_competition * 0.08
            + max(0.0, context_cluster_bias) * 0.08
            + max(0.0, signature_bias) * 0.06
            + max(0.0, directional_score) * 0.06
            + conviction_boost * 0.20
            + felt_bearing_score * 0.12
            - caution_penalty * 0.10,
        ),
    )

    target_conviction = max(
        0.0,
        min(
            1.0,
            (target_lock * 0.28)
            + (focus_confidence * 0.22)
            + (signal_relevance * 0.18)
            + (context_cluster_quality * 0.10)
            + (signature_quality * 0.08)
            + max(0.0, directional_score) * 0.08
            + conviction_boost * 0.26
            + felt_bearing_score * 0.14
            - caution_penalty * 0.10,
        ),
    )

    stress_pressure = max(
        0.0,
        min(
            1.0,
            max(0.0, float(snapshot_state.get("regulation_pressure", 0.0) or 0.0) / 2.2),
        ),
    )

    risk_distance = max(
        base_move * (
            0.42
            + (risk_model_score * 0.58)
            + (1.0 - target_conviction) * 0.12
            + (1.0 - reward_model_score) * 0.06
        ),
        close_price * float(getattr(Config, "MCM_MIN_SL_DISTANCE", 0.0022) or 0.0022),
        candle_span * 0.42,
    )

    protective_width_factor = max(
        0.82,
        min(
            1.12,
            1.0
            + (protective_width_regulation * 0.14)
            + (load_bearing_capacity * 0.04)
            + (stress_pressure * 0.10)
            + max(0.0, risk_model_score - reward_model_score) * 0.08
            - (protective_courage * 0.10)
            - (target_conviction * 0.12)
            - (inhibition_level * 0.04)
            + width_shift,
        ),
    )
    risk_distance *= protective_width_factor

    max_sl_pct = float(getattr(Config, "MAX_SL_DISTANCE", 0.0) or 0.0)
    if max_sl_pct > 0.0:
        gate_aligned_sl = close_price * max_sl_pct * float(getattr(Config, "MCM_PLAN_GATE_ALIGN", 0.92) or 0.92)
        risk_distance = min(
            risk_distance,
            max(
                gate_aligned_sl,
                close_price * float(getattr(Config, "MCM_MIN_SL_DISTANCE", 0.0022) or 0.0022),
            ),
        )

    min_reward_distance = close_price * float(getattr(Config, "MIN_TP_DISTANCE", 0.008) or 0.008)
    min_rr_target = max(
        float(getattr(Config, "MIN_RR", 1.0) or 1.0),
        1.15 + (target_conviction * 0.18) + (reward_model_score * 0.12) - (risk_model_score * 0.08),
    )
    min_rr_target = max(
        float(getattr(Config, "MIN_RR", min_rr_target) or min_rr_target),
        min_rr_target * (1.0 + rr_shift/2),
    )

    reward_distance = max(
        base_move * (
            0.82
            + (reward_model_score * 1.18)
            + (target_conviction * 0.42)
            - (risk_model_score * 0.12)
        ),
        min_reward_distance * (
            1.0
            + (reward_model_score * 0.22)
            + (target_conviction * 0.12)
            - (risk_model_score * 0.06)
        ),
        risk_distance * min_rr_target,
        min_reward_distance,
    )

    if self_state == "stressed":
        reward_distance *= 0.94
        risk_distance *= 1.0 + (stress_pressure * 0.06)
    elif self_state == "excited":
        reward_distance *= 1.06

    risk_distance *= max(0.84, 1.0 + risk_shift)

    if decision == "LONG":
        sl_price = entry_price - risk_distance
        tp_price = entry_price + reward_distance
    else:
        sl_price = entry_price + risk_distance
        tp_price = entry_price - reward_distance

    reward = abs(tp_price - entry_price)
    risk = abs(entry_price - sl_price)
    rr_value = reward / max(risk, 1e-9)

    return {
        "entry_price": float(entry_price),
        "sl_price": float(sl_price),
        "tp_price": float(tp_price),
        "rr_value": float(rr_value),
        "entry_validity_band": {
            "center": float(validity_center),
            "lower": float(validity_center - validity_halfwidth),
            "upper": float(validity_center + validity_halfwidth),
            "halfwidth": float(validity_halfwidth),
        },
        "target_conviction": float(target_conviction),
        "risk_model_score": float(risk_model_score),
        "reward_model_score": float(reward_model_score),
        "felt_bearing_score": float(felt_bearing_score),
        "felt_profile_label": str(felt_profile_label),
        "entry_mode": str(strategic_entry_mode),
        "impulse_entry_price": float(impulse_entry_price),
        "strategic_entry_price": float(strategic_entry_price),
        "strategic_entry_weight": float(strategic_entry_weight),
        "strategic_entry_fit": float(strategic_entry_fit),
        "area_motor_intention": float(area_motor_intention),
        "area_motor_distance_fit": float(area_motor_distance_fit),
        "impulse_entry_intention": float(impulse_entry_intention),
        "area_entry_intention": float(area_entry_intention),
        "entry_choice_conflict": float(entry_choice_conflict),
        "entry_choice_bearing": float(entry_choice_bearing),
        "area_direct_readiness": float(area_direct_readiness),
        "area_motor_restraint": float(area_motor_restraint),
        "entry_choice_state": str(entry_choice_state),
        "strategic_area_focus_id": str(strategic_area_focus_id),
        "strategic_area_price_low": float(strategic_area_low),
        "strategic_area_price_high": float(strategic_area_high),
    }

# --------------------------------------------------
# FUSION
# --------------------------------------------------
def resolve_fused_decision(candle_state, tension_state, mcm_snapshot, bot=None, temporal_perception_state=None):

    coherence = float(tension_state.get("coherence", 0.0) or 0.0)
    close_position = float(candle_state.get("close_position", 0.0) or 0.0)
    wick_bias = float(candle_state.get("wick_bias", 0.0) or 0.0)
    return_intensity = float(candle_state.get("return_intensity", 0.0) or 0.0)

    long_score = (coherence * 0.95) + (close_position * 0.75) + (wick_bias * 0.35) + (return_intensity * 0.45)
    short_score = (-coherence * 0.95) + (-close_position * 0.75) + (-wick_bias * 0.35) + (-return_intensity * 0.45)

    memory = mcm_snapshot.get("strongest_memory") or {}
    memory_center = float(memory.get("center", 0.0) or 0.0)
    memory_strength = float(memory.get("strength", 0.0) or 0.0)

    focus_point = 0.0
    focus_confidence = 0.0
    target_lock = 0.0
    target_drift = 0.0
    inhibition_level = 0.0
    habituation_level = 0.0
    competition_bias = 0.0
    observation_mode = False
    temporal_state = dict(temporal_perception_state or {})

    if bot is not None:
        focus_point = float(getattr(bot, "focus_point", 0.0) or 0.0)
        focus_confidence = float(getattr(bot, "focus_confidence", 0.0) or 0.0)
        target_lock = float(getattr(bot, "target_lock", 0.0) or 0.0)
        target_drift = float(getattr(bot, "target_drift", 0.0) or 0.0)
        inhibition_level = float(getattr(bot, "inhibition_level", 0.0) or 0.0)
        habituation_level = float(getattr(bot, "habituation_level", 0.0) or 0.0)
        competition_bias = float(getattr(bot, "competition_bias", 0.0) or 0.0)
        observation_mode = bool(getattr(bot, "observation_mode", False))
        if not temporal_state:
            temporal_state = dict(getattr(bot, "temporal_perception_state", {}) or {})

    affective = _resolve_affective_context_modulation(
        bot=bot,
        fused_state={
            "context_cluster_id": getattr(bot, "last_context_cluster_id", "-") if bot is not None else "-",
        },
    )
    temporal_modulation = _resolve_temporal_decision_modulation(temporal_state)

    long_score += float(temporal_modulation.get("long_bias", 0.0) or 0.0)
    short_score += float(temporal_modulation.get("short_bias", 0.0) or 0.0)
    felt_bearing_score = float(affective.get("felt_bearing_score", 0.0) or 0.0)
    felt_profile_label = str(affective.get("felt_profile_label", "mixed_unclear") or "mixed_unclear")
    decision_bias = float(affective.get("decision_bias", 0.0) or 0.0)
    conviction_boost = float(affective.get("conviction_boost", 0.0) or 0.0)
    caution_penalty = float(affective.get("caution_penalty", 0.0) or 0.0)
    volatility_penalty = float(affective.get("volatility_penalty", 0.0) or 0.0)
    risk_shift = float(affective.get("risk_shift", 0.0) or 0.0)
    rr_shift = float(affective.get("rr_shift", 0.0) or 0.0)

    pressure_weight = float(getattr(Config, "MCM_PRESSURE_WEIGHT", 0.35) or 0.35)
    memory_weight = float(getattr(Config, "MCM_MEMORY_WEIGHT", 0.20) or 0.20)
    regulation_weight = float(getattr(Config, "MCM_REGULATION_WEIGHT", 0.25) or 0.25)

    mcm_direction = (
        float(mcm_snapshot.get("mean_energy", 0.0) or 0.0) * pressure_weight
        + float(mcm_snapshot.get("mean_motivation", 0.0) or 0.0) * 0.10
        + memory_center * memory_weight
    )

    regulation_pressure = float(mcm_snapshot.get("regulation_pressure", 0.0) or 0.0)
    memory_penalty = min(0.42, max(0.0, memory_strength - 12.0) * 0.012)
    regulation_penalty = min(
        0.52,
        max(0.0, regulation_pressure - 0.85) * (regulation_weight * 0.34),
    )

    focus_long_bias = max(0.0, focus_point) * (0.20 + target_lock * 0.14 + focus_confidence * 0.10)
    focus_short_bias = max(0.0, -focus_point) * (0.20 + target_lock * 0.14 + focus_confidence * 0.10)
    drift_penalty = max(0.0, abs(target_drift) - 0.28) * 0.12
    inhibition_penalty = inhibition_level * 0.18
    habituation_penalty = habituation_level * 0.12
    competition_long_bias = max(0.0, competition_bias) * 0.28
    competition_short_bias = max(0.0, -competition_bias) * 0.28
    affective_long_bias = decision_bias + (conviction_boost * 0.42) - caution_penalty - volatility_penalty
    affective_short_bias = decision_bias + (conviction_boost * 0.42) - caution_penalty - volatility_penalty

    long_score = long_score + mcm_direction - regulation_penalty - memory_penalty + focus_long_bias + competition_long_bias - drift_penalty - inhibition_penalty - habituation_penalty + affective_long_bias
    short_score = short_score - mcm_direction - regulation_penalty - memory_penalty + focus_short_bias + competition_short_bias - drift_penalty - inhibition_penalty - habituation_penalty + affective_short_bias

    selected_attractor = str(mcm_snapshot.get("attractor", "neutral") or "neutral")
    self_state = str(mcm_snapshot.get("self_state", "stable") or "stable")

    long_allowed = True
    short_allowed = True
    reject_reason = None

    if selected_attractor == "defense":
        long_score -= 0.10
        short_score -= 0.10
        if abs(coherence) < 0.10 and abs(return_intensity) < 0.06:
            long_allowed = False
            short_allowed = False
            reject_reason = "defense_block"
    elif selected_attractor == "explore":
        long_score -= 0.03
        short_score -= 0.03
    elif selected_attractor == "analysis":
        long_score -= 0.08
        short_score -= 0.08
    elif selected_attractor == "cooperate":
        if abs(coherence) < 0.10:
            long_score -= 0.04
            short_score -= 0.04

    if self_state == "stressed":
        long_score -= 0.14
        short_score -= 0.14
        if abs(coherence) < 0.12 and abs(return_intensity) < 0.08:
            long_allowed = False
            short_allowed = False
            reject_reason = "stressed_block"

    elif self_state == "excited":
        long_score -= 0.03
        short_score -= 0.03

    if abs(return_intensity) < 0.05:
        long_score -= 0.03
        short_score -= 0.03

    if observation_mode:
        long_score -= 0.10
        short_score -= 0.10
        if reject_reason is None and max(long_score, short_score) < 0.34:
            long_allowed = False
            short_allowed = False
            reject_reason = "observation_mode"

    if bool(getattr(Config, "MCM_ATTRACTOR_LONG_ALLOW", True)) is False:
        long_allowed = False

    if bool(getattr(Config, "MCM_ATTRACTOR_SHORT_ALLOW", True)) is False:
        short_allowed = False

    min_score = 0.18 + max(0.0, caution_penalty * 0.18) + max(0.0, volatility_penalty * 0.12)
    min_edge = 0.08 + max(0.0, caution_penalty * 0.10)

    side = "WAIT"
    best_score = 0.0

    if long_allowed and long_score > min_score and (long_score - short_score) > min_edge:
        side = "LONG"
        best_score = long_score
    elif short_allowed and short_score > min_score and (short_score - long_score) > min_edge:
        side = "SHORT"
        best_score = short_score
    elif reject_reason is None:
        reject_reason = "fused_score_too_low"

    min_rr_floor = max(0.0, float(getattr(Config, "MIN_RR", 1.0) or 1.0))
    endogenous_rr_lift = max(
        0.0,
        (abs(best_score) * 0.18)
        + (focus_confidence * 0.14)
        + (target_lock * 0.12)
        + (conviction_boost * 0.16)
        + (felt_bearing_score * 0.10)
        - (caution_penalty * 0.12)
        - (volatility_penalty * 0.10)
    )
    rr_value = min_rr_floor + endogenous_rr_lift
    risk_pct = float(getattr(Config, "BASE_RISK_PCT", 0.01) or 0.01)

    if self_state == "stressed":
        risk_pct *= float(getattr(Config, "MCM_STRESS_RISK_FACTOR", 0.75) or 0.75)
        rr_value = max(min_rr_floor, rr_value * 0.92)
    elif self_state == "excited":
        rr_value *= 1.0 + min(0.10, endogenous_rr_lift * 0.16)

    risk_pct = max(0.0005, risk_pct * (1.0 + risk_shift))
    rr_value = max(min_rr_floor, rr_value * (1.0 + rr_shift))

    _mcm_decision_debug(
        "MCM_DECISION | "
        f"long_score={long_score:.4f} "
        f"short_score={short_score:.4f} "
        f"memory_center={memory_center:.4f} "
        f"memory_strength={memory_strength:.0f} "
        f"self_state={self_state} "
        f"attractor={selected_attractor} "
        f"felt_bearing_score={felt_bearing_score:.4f} "
        f"felt_profile_label={felt_profile_label} "
        f"best_score={best_score:.4f} "
        f"reject_reason={reject_reason or '-'}"
    )

    return {
        "decision": side,
        "rr_value": float(rr_value),
        "risk_pct": float(risk_pct),
        "long_score": float(long_score),
        "short_score": float(short_score),
        "self_state": self_state,
        "attractor": selected_attractor,
        "reject_reason": reject_reason,
        "inhibition_level": float(inhibition_level),
        "habituation_level": float(habituation_level),
        "competition_bias": float(competition_bias),
        "observation_mode": bool(observation_mode),
        "felt_bearing_score": float(felt_bearing_score),
        "felt_profile_label": str(felt_profile_label),
    }

# --------------------------------------------------
# update target model
# --------------------------------------------------
def update_target_model(bot, candle_state, focus):

    if bot is None:
        return None

    focus_point = float(focus.get("focus_direction", 0.0) or 0.0)
    focus_confidence = float(focus.get("focus_confidence", 0.0) or 0.0)
    target_lock = float(focus.get("target_lock", 0.0) or 0.0)
    return_intensity = float(candle_state.get("return_intensity", 0.0) or 0.0)

    previous_focus_point = float(getattr(bot, "focus_point", 0.0) or 0.0)

    bot.focus_point = float((previous_focus_point * 0.55) + (focus_point * 0.45))
    bot.focus_confidence = float((float(getattr(bot, "focus_confidence", 0.0) or 0.0) * 0.45) + (focus_confidence * 0.55))
    bot.target_lock = float((float(getattr(bot, "target_lock", 0.0) or 0.0) * 0.40) + (target_lock * 0.60))
    bot.target_drift = float(return_intensity - bot.focus_point)

    return {
        "focus_point": float(bot.focus_point),
        "focus_confidence": float(bot.focus_confidence),
        "target_lock": float(bot.target_lock),
        "target_drift": float(bot.target_drift),
    }

# --------------------------------------------------
def update_expectation_pressure_state(bot, candle_state, stimulus, snapshot, decision="WAIT", visual_market_state=None):

    if bot is None:
        return None

    focus = dict((stimulus or {}).get("focus", {}) or {})
    filtered_vision = dict((stimulus or {}).get("filtered_vision", {}) or {})
    snapshot_state = dict(snapshot or {})
    candle = dict(candle_state or {})
    visual = dict(visual_market_state or {})

    focus_confidence = float(focus.get("focus_confidence", 0.0) or 0.0)
    target_lock = float(focus.get("target_lock", 0.0) or 0.0)
    signal_relevance = float(focus.get("signal_relevance", 0.0) or 0.0)
    noise_damp = float(focus.get("noise_damp", 0.0) or 0.0)
    filtered_target_map = float(filtered_vision.get("target_map", 0.0) or 0.0)
    filtered_threat_map = float(filtered_vision.get("threat_map", 0.0) or 0.0)
    filtered_optic_flow = float(filtered_vision.get("optic_flow", 0.0) or 0.0)
    return_intensity = float(candle.get("return_intensity", 0.0) or 0.0)
    close_position = float(candle.get("close_position", 0.0) or 0.0)
    directional_bias = float(visual.get("directional_bias", 0.0) or 0.0)
    range_position = float(visual.get("range_position", 0.0) or 0.0)
    market_balance = float(visual.get("market_balance", 0.0) or 0.0)
    breakout_tension = float(visual.get("breakout_tension", 0.0) or 0.0)
    visual_coherence = float(visual.get("visual_coherence", 0.0) or 0.0)

    prior_entry_expectation = float(getattr(bot, "entry_expectation", 0.0) or 0.0)
    prior_target_expectation = float(getattr(bot, "target_expectation", 0.0) or 0.0)
    prior_approach_pressure = float(getattr(bot, "approach_pressure", 0.0) or 0.0)
    prior_pressure_release = float(getattr(bot, "pressure_release", 0.0) or 0.0)
    experience_regulation = float(getattr(bot, "experience_regulation", 0.0) or 0.0)
    reflection_maturity = float(getattr(bot, "reflection_maturity", 0.0) or 0.0)
    load_bearing_capacity = float(getattr(bot, "load_bearing_capacity", 0.0) or 0.0)
    protective_width_regulation = float(getattr(bot, "protective_width_regulation", 0.0) or 0.0)
    protective_courage = float(getattr(bot, "protective_courage", 0.0) or 0.0)
    inhibition_level = float(getattr(bot, "inhibition_level", 0.0) or 0.0)
    observation_mode = bool(getattr(bot, "observation_mode", False))
    stress_pressure = max(
        0.0,
        min(
            1.0,
            max(0.0, float(snapshot_state.get("regulation_pressure", 0.0) or 0.0) / 2.2),
        ),
    )

    decision_value = str(decision or "WAIT").upper().strip()
    has_position = isinstance(getattr(bot, "position", None), dict)
    has_pending_entry = isinstance(getattr(bot, "pending_entry", None), dict)

    if decision_value == "LONG":
        directional_entry_bias = max(0.0, directional_bias)
    elif decision_value == "SHORT":
        directional_entry_bias = max(0.0, -directional_bias)
    else:
        directional_entry_bias = max(0.0, abs(directional_bias) - 0.12)

    range_drive = max(0.0, abs(range_position) - 0.15)

    entry_anchor = max(
        0.0,
        min(
            1.0,
            (target_lock * 0.26)
            + (focus_confidence * 0.22)
            + (signal_relevance * 0.16)
            + (max(0.0, filtered_target_map) * 0.08)
            + (max(0.0, filtered_optic_flow) * 0.04)
            + (directional_entry_bias * 0.10)
            + (market_balance * 0.08)
            + (visual_coherence * 0.08)
            - (noise_damp * 0.06)
            - (filtered_threat_map * 0.04)
            - (breakout_tension * 0.02),
        ),
    )

    target_anchor = max(
        0.0,
        min(
            1.0,
            (target_lock * 0.28)
            + (focus_confidence * 0.14)
            + (signal_relevance * 0.12)
            + (max(0.0, filtered_target_map) * 0.10)
            + (max(0.0, abs(close_position)) * 0.04)
            + (directional_entry_bias * 0.08)
            + (range_drive * 0.08)
            + (market_balance * 0.08)
            + (visual_coherence * 0.08)
            - (noise_damp * 0.04)
            - (breakout_tension * 0.02),
        ),
    )

    if has_position:
        entry_expectation_target = 0.0
        target_expectation_target = min(1.0, target_anchor + 0.18)
    elif has_pending_entry or decision_value in ("LONG", "SHORT"):
        entry_expectation_target = min(1.0, entry_anchor + 0.16)
        target_expectation_target = target_anchor * 0.35
    else:
        entry_expectation_target = entry_anchor
        target_expectation_target = 0.0

    if observation_mode:
        entry_expectation_target *= 0.82
        target_expectation_target *= 0.86

    expectation_bias = max(entry_expectation_target, target_expectation_target)
    approach_gain = max(
        0.0,
        (expectation_bias * 0.24)
        + (max(0.0, 0.45 - abs(float(getattr(bot, "target_drift", 0.0) or 0.0))) * 0.28)
        + (max(0.0, abs(return_intensity)) * 0.08)
        + (directional_entry_bias * 0.10)
        + (market_balance * 0.08)
        + (visual_coherence * 0.06)
        + (breakout_tension * 0.08)
        - (inhibition_level * 0.10)
        - (experience_regulation * 0.06),
    )

    missed_release = 0.0
    if decision_value == "WAIT" and prior_entry_expectation > 0.34 and prior_approach_pressure > 0.24:
        missed_release = min(1.0, (prior_entry_expectation * 0.42) + (prior_approach_pressure * 0.58))
    elif has_position is False and has_pending_entry is False and prior_target_expectation > 0.30 and prior_approach_pressure > 0.20:
        missed_release = min(1.0, (prior_target_expectation * 0.36) + (prior_approach_pressure * 0.52))

    release_decay = max(0.0, prior_pressure_release * 0.62)
    bot.entry_expectation = float(max(0.0, min(1.0, (prior_entry_expectation * 0.52) + (entry_expectation_target * 0.48))))
    bot.target_expectation = float(max(0.0, min(1.0, (prior_target_expectation * 0.54) + (target_expectation_target * 0.46))))
    bot.approach_pressure = float(max(0.0, min(1.0, (prior_approach_pressure * 0.58) + approach_gain - (missed_release * 0.44))))
    bot.pressure_release = float(max(0.0, min(1.0, release_decay + missed_release)))
    bot.experience_regulation = float(max(0.0, min(1.0, (experience_regulation * 0.985) + (reflection_maturity * 0.010))))
    bot.reflection_maturity = float(max(0.0, min(1.0, (reflection_maturity * 0.996) + (abs(snapshot_state.get("mean_velocity", 0.0) or 0.0) * 0.002))))
    bot.load_bearing_capacity = float(max(0.0, min(1.0, (load_bearing_capacity * 0.82) + (bot.experience_regulation * 0.11) + (bot.reflection_maturity * 0.08) - (bot.pressure_release * 0.03))))
    bot.protective_width_regulation = float(max(0.0, min(
        1.0,
        (protective_width_regulation * 0.66)
        + (bot.approach_pressure * 0.18)
        + (bot.pressure_release * 0.26)
        + (bot.experience_regulation * 0.22)
        + (bot.reflection_maturity * 0.12)
        + (stress_pressure * 0.10)
        + (breakout_tension * 0.16)
        + (max(0.0, 1.0 - market_balance) * 0.10)
        - (visual_coherence * 0.06)
        - (inhibition_level * 0.06),
    )))
    bot.protective_courage = float(max(0.0, min(
        0.86,
        (protective_courage * 0.70)
        + (bot.load_bearing_capacity * 0.18)
        + (bot.reflection_maturity * 0.10)
        + (max(0.0, 1.0 - noise_damp) * 0.05)
        + (market_balance * 0.06)
        + (visual_coherence * 0.08)
        - (bot.pressure_release * 0.12)
        - (filtered_threat_map * 0.08)
        - (breakout_tension * 0.08),
    )))

    return {
        "entry_expectation": float(bot.entry_expectation),
        "target_expectation": float(bot.target_expectation),
        "approach_pressure": float(bot.approach_pressure),
        "pressure_release": float(bot.pressure_release),
        "experience_regulation": float(bot.experience_regulation),
        "reflection_maturity": float(bot.reflection_maturity),
        "load_bearing_capacity": float(bot.load_bearing_capacity),
        "protective_width_regulation": float(bot.protective_width_regulation),
        "protective_courage": float(bot.protective_courage),
    }

# --------------------------------------------------
def update_experience_state(bot, outcome_reason):

    if bot is None:
        return None

    reason = str(outcome_reason or "").strip().lower()

    prior_release = float(getattr(bot, "pressure_release", 0.0) or 0.0)
    prior_regulation = float(getattr(bot, "experience_regulation", 0.0) or 0.0)
    prior_maturity = float(getattr(bot, "reflection_maturity", 0.0) or 0.0)
    prior_entry_expectation = float(getattr(bot, "entry_expectation", 0.0) or 0.0)
    prior_target_expectation = float(getattr(bot, "target_expectation", 0.0) or 0.0)
    prior_pressure = float(getattr(bot, "approach_pressure", 0.0) or 0.0)
    prior_load_bearing_capacity = float(getattr(bot, "load_bearing_capacity", 0.0) or 0.0)
    prior_protective_width_regulation = float(getattr(bot, "protective_width_regulation", 0.0) or 0.0)
    prior_protective_courage = float(getattr(bot, "protective_courage", 0.0) or 0.0)

    attempt_feedback = {}
    stats = getattr(bot, "stats", None)
    if stats is not None and hasattr(stats, "get_attempt_feedback"):
        try:
            attempt_feedback = dict(stats.get_attempt_feedback() or {})
        except Exception:
            attempt_feedback = {}

    attempt_density = float(attempt_feedback.get("attempt_density", 0.0) or 0.0)
    overtrade_pressure = float(attempt_feedback.get("overtrade_pressure", 0.0) or 0.0)
    context_quality = float(attempt_feedback.get("context_quality", 0.0) or 0.0)
    blocked_ratio = float(attempt_feedback.get("blocked_ratio", 0.0) or 0.0)
    timeout_ratio = float(attempt_feedback.get("timeout_ratio", 0.0) or 0.0)
    fill_ratio = float(attempt_feedback.get("fill_ratio", 0.0) or 0.0)

    release_gain = 0.0
    regulation_gain = 0.0
    maturity_gain = 0.0

    if reason == "tp_hit":
        release_gain = 0.72 + (prior_pressure * 0.18)
        regulation_gain = 0.08 + (prior_target_expectation * 0.06)
        maturity_gain = 0.04
    elif reason == "sl_hit":
        release_gain = 0.82 + (prior_pressure * 0.22)
        regulation_gain = 0.05 + (prior_regulation * 0.02)
        maturity_gain = 0.06
    elif reason in ("cancel", "timeout"):
        release_gain = 0.58 + (prior_entry_expectation * 0.18)
        regulation_gain = 0.04
        maturity_gain = 0.05
    elif reason in ("reward_too_small", "rr_too_low", "sl_distance_too_high"):
        release_gain = 0.46 + (prior_entry_expectation * 0.16)
        regulation_gain = 0.03
        maturity_gain = 0.04

    release_gain += (attempt_density * 0.08) + (overtrade_pressure * 0.12)
    regulation_gain += (context_quality * 0.10) + (fill_ratio * 0.06) - (overtrade_pressure * 0.10) - (timeout_ratio * 0.06)
    maturity_gain += (context_quality * 0.08) + (fill_ratio * 0.04) + (blocked_ratio * 0.02) - (overtrade_pressure * 0.06)

    bot.pressure_release = float(max(0.0, min(1.0, (prior_release * 0.30) + release_gain)))
    bot.approach_pressure = float(max(0.0, min(1.0, (prior_pressure * 0.36) + (attempt_density * 0.18) + (overtrade_pressure * 0.26) - (context_quality * 0.14))))
    bot.entry_expectation = float(max(0.0, min(1.0, (prior_entry_expectation * 0.42) - (overtrade_pressure * 0.10) + (context_quality * 0.04))))
    bot.target_expectation = float(max(0.0, min(1.0, (prior_target_expectation * 0.34) - (overtrade_pressure * 0.08) + (fill_ratio * 0.06))))
    bot.experience_regulation = float(max(0.0, min(1.0, (prior_regulation * 0.82) + regulation_gain + (prior_maturity * 0.04))))
    bot.reflection_maturity = float(max(0.0, min(1.0, (prior_maturity * 0.96) + maturity_gain + (abs(release_gain - regulation_gain) * 0.04))))
    bot.load_bearing_capacity = float(max(0.0, min(
        1.0,
        (prior_load_bearing_capacity * 0.76)
        + (bot.experience_regulation * 0.22)
        + (bot.reflection_maturity * 0.16)
        - (bot.pressure_release * 0.10)
        - (overtrade_pressure * 0.08),
    )))
    bot.protective_width_regulation = float(max(0.0, min(
        1.0,
        (prior_protective_width_regulation * 0.58)
        + (bot.pressure_release * 0.36)
        + (bot.experience_regulation * 0.28)
        + (bot.reflection_maturity * 0.18)
        + (prior_pressure * 0.14)
        + (overtrade_pressure * 0.12),
    )))
    bot.protective_courage = float(max(0.0, min(
        0.86,
        (prior_protective_courage * 0.62)
        + (bot.load_bearing_capacity * 0.16)
        + (bot.reflection_maturity * 0.10)
        - (bot.pressure_release * 0.16)
        - (overtrade_pressure * 0.12)
        + (context_quality * 0.08),
    )))

    return {
        "entry_expectation": float(bot.entry_expectation),
        "target_expectation": float(bot.target_expectation),
        "approach_pressure": float(bot.approach_pressure),
        "pressure_release": float(bot.pressure_release),
        "experience_regulation": float(bot.experience_regulation),
        "reflection_maturity": float(bot.reflection_maturity),
        "load_bearing_capacity": float(bot.load_bearing_capacity),
        "protective_width_regulation": float(bot.protective_width_regulation),
        "protective_courage": float(bot.protective_courage),
        "attempt_density": float(attempt_density),
        "overtrade_pressure": float(overtrade_pressure),
        "context_quality": float(context_quality),
        "fill_ratio": float(fill_ratio),
        "blocked_ratio": float(blocked_ratio),
        "timeout_ratio": float(timeout_ratio),
    }

# --------------------------------------------------
def build_state_signature(candle_state, tension_state, snapshot, stimulus, bot=None):

    focus = dict(stimulus.get("focus", {}) or {})
    filtered_vision = dict(stimulus.get("filtered_vision", {}) or {})
    strongest_memory = dict((snapshot.get("strongest_memory") or {}) or {})

    focus_point = float(getattr(bot, "focus_point", 0.0) or 0.0) if bot is not None else 0.0
    focus_confidence = float(getattr(bot, "focus_confidence", 0.0) or 0.0) if bot is not None else 0.0
    target_lock = float(getattr(bot, "target_lock", 0.0) or 0.0) if bot is not None else 0.0
    target_drift = float(getattr(bot, "target_drift", 0.0) or 0.0) if bot is not None else 0.0
    entry_expectation = float(getattr(bot, "entry_expectation", 0.0) or 0.0) if bot is not None else 0.0
    target_expectation = float(getattr(bot, "target_expectation", 0.0) or 0.0) if bot is not None else 0.0
    approach_pressure = float(getattr(bot, "approach_pressure", 0.0) or 0.0) if bot is not None else 0.0
    pressure_release = float(getattr(bot, "pressure_release", 0.0) or 0.0) if bot is not None else 0.0
    experience_regulation = float(getattr(bot, "experience_regulation", 0.0) or 0.0) if bot is not None else 0.0
    reflection_maturity = float(getattr(bot, "reflection_maturity", 0.0) or 0.0) if bot is not None else 0.0
    load_bearing_capacity = float(getattr(bot, "load_bearing_capacity", 0.0) or 0.0) if bot is not None else 0.0
    protective_width_regulation = float(getattr(bot, "protective_width_regulation", 0.0) or 0.0) if bot is not None else 0.0
    protective_courage = float(getattr(bot, "protective_courage", 0.0) or 0.0) if bot is not None else 0.0

    coherence = float(tension_state.get("coherence", 0.0) or 0.0)
    energy = float(tension_state.get("energy", 0.0) or 0.0)
    asymmetry = int(tension_state.get("asymmetry", 0) or 0)
    return_intensity = float(candle_state.get("return_intensity", 0.0) or 0.0)
    close_position = float(candle_state.get("close_position", 0.0) or 0.0)

    signal_relevance = float(focus.get("signal_relevance", 0.0) or 0.0)
    noise_damp = float(focus.get("noise_damp", 0.0) or 0.0)
    filtered_target_map = float(filtered_vision.get("target_map", 0.0) or 0.0)
    filtered_threat_map = float(filtered_vision.get("threat_map", 0.0) or 0.0)

    memory_center = float(strongest_memory.get("center", 0.0) or 0.0)
    memory_strength = int(strongest_memory.get("strength", 0) or 0)

    attractor = str(snapshot.get("attractor", "neutral") or "neutral")
    self_state = str(snapshot.get("self_state", "stable") or "stable")

    attractor_code = {
        "defense": -2,
        "analysis": -1,
        "neutral": 0,
        "cooperate": 1,
        "explore": 2,
    }.get(attractor, 0)

    self_state_code = {
        "stressed": -1,
        "stable": 0,
        "active": 1,
        "excited": 2,
    }.get(self_state, 0)

    signature_vector = [
        round(float(energy), 2),
        round(float(coherence), 2),
        int(asymmetry),
        round(float(close_position), 2),
        round(float(return_intensity), 2),
        round(float(focus_point), 2),
        round(float(focus_confidence), 2),
        round(float(target_lock), 2),
        round(float(target_drift), 2),
        round(float(entry_expectation), 2),
        round(float(target_expectation), 2),
        round(float(approach_pressure), 2),
        round(float(pressure_release), 2),
        round(float(experience_regulation), 2),
        round(float(reflection_maturity), 2),
        round(float(load_bearing_capacity), 2),
        round(float(protective_width_regulation), 2),
        round(float(protective_courage), 2),
        round(float(signal_relevance), 2),
        round(float(noise_damp), 2),
        round(float(filtered_target_map), 2),
        round(float(filtered_threat_map), 2),
        round(float(memory_center), 2),
        int(memory_strength),
        int(attractor_code),
        int(self_state_code),
    ]

    signature_key = "|".join(
        [
            f"e:{round(float(energy) / 0.25) * 0.25:.2f}",
            f"c:{round(float(coherence) / 0.20) * 0.20:.2f}",
            f"a:{int(asymmetry)}",
            f"cp:{round(float(close_position) / 0.25) * 0.25:.2f}",
            f"ri:{round(float(return_intensity) / 0.20) * 0.20:.2f}",
            f"fp:{round(float(focus_point) / 0.20) * 0.20:.2f}",
            f"fc:{round(float(focus_confidence) / 0.20) * 0.20:.2f}",
            f"tl:{round(float(target_lock) / 0.20) * 0.20:.2f}",
            f"td:{round(float(target_drift) / 0.20) * 0.20:.2f}",
            f"ee:{round(float(entry_expectation) / 0.20) * 0.20:.2f}",
            f"te:{round(float(target_expectation) / 0.20) * 0.20:.2f}",
            f"ap:{round(float(approach_pressure) / 0.20) * 0.20:.2f}",
            f"pr:{round(float(pressure_release) / 0.20) * 0.20:.2f}",
            f"er:{round(float(experience_regulation) / 0.20) * 0.20:.2f}",
            f"rm:{round(float(reflection_maturity) / 0.20) * 0.20:.2f}",
            f"lb:{round(float(load_bearing_capacity) / 0.20) * 0.20:.2f}",
            f"pw:{round(float(protective_width_regulation) / 0.20) * 0.20:.2f}",
            f"pc:{round(float(protective_courage) / 0.20) * 0.20:.2f}",
            f"sr:{round(float(signal_relevance) / 0.20) * 0.20:.2f}",
            f"nd:{round(float(noise_damp) / 0.20) * 0.20:.2f}",
            f"tm:{round(float(filtered_target_map) / 0.25) * 0.25:.2f}",
            f"th:{round(float(filtered_threat_map) / 0.25) * 0.25:.2f}",
            f"mc:{round(float(memory_center) / 0.25) * 0.25:.2f}",
            f"ms:{int(min(12, max(0, memory_strength)))}",
            f"at:{int(attractor_code)}",
            f"ss:{int(self_state_code)}",
        ]
    )

    return {
        "signature_key": str(signature_key),
        "signature_vector": list(signature_vector),
        "attractor_code": int(attractor_code),
        "self_state_code": int(self_state_code),
    }

# --------------------------------------------------
# internal form symbols
# --------------------------------------------------
def _quantize_form_axis(value, step=0.20, min_value=-2.0, max_value=2.0):

    try:
        raw = float(value or 0.0)
    except Exception:
        raw = 0.0

    step_value = max(0.01, float(step or 0.20))
    bounded = max(float(min_value), min(float(max_value), raw))
    return round(round(bounded / step_value) * step_value, 4)

def _form_symbol_memory_path(path=None):

    if path is not None:
        return str(path)

    configured = getattr(Config, "MCM_FORM_SYMBOL_MEMORY_PATH", "bot_memory/form_symbol_memory.json")
    return str(configured or "bot_memory/form_symbol_memory.json")

def _normalize_form_symbol_memory_symbols(symbols):

    if not isinstance(symbols, dict):
        return {}

    normalized = {}
    max_symbols = max(32, int(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_MAX_SYMBOLS", 1024) or 1024))
    max_variants = max(1, int(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_MAX_VARIANTS", 12) or 12))

    def _num(item, key, default=0.0):
        try:
            return float((item or {}).get(key, default) or default)
        except Exception:
            return float(default)

    candidates = []
    for symbol_id, raw_item in dict(symbols or {}).items():
        if not isinstance(raw_item, dict):
            continue

        symbol_key = str(symbol_id or raw_item.get("symbol_id", "") or "").strip()
        if not symbol_key:
            continue

        item = dict(raw_item or {})
        seen = max(0, int(_num(item, "seen", 0)))
        variants = dict(item.get("variants", {}) or {})
        cleaned_variants = {}
        for variant_key, variant_item in sorted(
            variants.items(),
            key=lambda kv: int((kv[1] or {}).get("seen", 0) or 0) if isinstance(kv[1], dict) else 0,
            reverse=True,
        )[:max_variants]:
            if not isinstance(variant_item, dict):
                continue
            cleaned_variants[str(variant_key)] = {
                "seen": max(0, int(_num(variant_item, "seen", 0))),
                "distance": max(0.0, min(1.0, _num(variant_item, "distance", 0.0))),
                "bearing": max(0.0, min(1.0, _num(variant_item, "bearing", 0.0))),
                "fragility": max(0.0, min(1.0, _num(variant_item, "fragility", 0.0))),
                "visual_blindness": max(0.0, min(1.0, _num(variant_item, "visual_blindness", 0.0))),
                "visual_clarity": max(0.0, min(1.0, _num(variant_item, "visual_clarity", 0.0))),
                "object_stability": max(0.0, min(1.0, _num(variant_item, "object_stability", 0.0))),
                "uncertain_exposure": max(0.0, min(1.0, _num(variant_item, "uncertain_exposure", 0.0))),
                "last_seen_ts": variant_item.get("last_seen_ts", None),
            }

        avg_vector = []
        for value in list(item.get("avg_vector", []) or [])[:32]:
            try:
                avg_vector.append(float(value))
            except Exception:
                continue

        cleaned = {
            "symbol_id": str(symbol_key),
            "form_key": str(item.get("form_key", item.get("family_key", "")) or ""),
            "family_key": str(item.get("family_key", item.get("form_key", "")) or ""),
            "scope": str(item.get("scope", "") or ""),
            "abstraction_level": max(0, int(_num(item, "abstraction_level", 0))),
            "seen": int(seen),
            "avg_vector": list(avg_vector or []),
            "variance": max(0.0, min(1.0, _num(item, "variance", 0.0))),
            "maturity": max(0.0, min(1.0, _num(item, "maturity", 0.0))),
            "stability": max(0.0, min(1.0, _num(item, "stability", 0.0))),
            "resonance": max(0.0, min(1.0, _num(item, "resonance", 0.0))),
            "bearing": max(0.0, min(1.0, _num(item, "bearing", 0.0))),
            "fragility": max(0.0, min(1.0, _num(item, "fragility", 0.0))),
            "resolution_quality": max(0.0, min(1.0, _num(item, "resolution_quality", 0.0))),
            "detail_pressure": max(0.0, min(1.0, _num(item, "detail_pressure", 0.0))),
            "symbolic_object_distance": max(0.0, min(1.0, _num(item, "symbolic_object_distance", 0.0))),
            "symbolic_containment": max(0.0, min(1.0, _num(item, "symbolic_containment", 0.0))),
            "symbolic_field_decoupling": max(0.0, min(1.0, _num(item, "symbolic_field_decoupling", 0.0))),
            "development_quality": max(-1.0, min(1.0, _num(item, "development_quality", 0.0))),
            "action_affinity": max(0.0, min(1.0, _num(item, "action_affinity", 0.50))),
            "observation_affinity": max(0.0, min(1.0, _num(item, "observation_affinity", 0.0))),
            "context_reframe_potential": max(0.0, min(1.0, _num(item, "context_reframe_potential", 0.0))),
            "learning_trust": max(0.0, min(1.0, _num(item, "learning_trust", 0.0))),
            "action_trust": max(0.0, min(1.0, _num(item, "action_trust", 0.0))),
            "caution_trust": max(0.0, min(1.0, _num(item, "caution_trust", 0.0))),
            "contact_maturity": max(0.0, min(1.0, _num(item, "contact_maturity", 0.0))),
            "contact_utility": max(0.0, min(1.0, _num(item, "contact_utility", 0.0))),
            "contact_pain_memory": max(0.0, min(1.0, _num(item, "contact_pain_memory", 0.0))),
            "contact_carefulness": max(0.0, min(1.0, _num(item, "contact_carefulness", 0.0))),
            "contact_burden_evidence": max(0.0, min(1.0, _num(item, "contact_burden_evidence", 0.0))),
            "contact_utility_evidence": max(0.0, min(1.0, _num(item, "contact_utility_evidence", 0.0))),
            "contact_learning_state": str(item.get("contact_learning_state", "unformed_contact") or "unformed_contact"),
            "constructive_seen": max(0, int(_num(item, "constructive_seen", 0))),
            "unconstructive_seen": max(0, int(_num(item, "unconstructive_seen", 0))),
            "last_zoom_need": max(0.0, min(1.0, _num(item, "last_zoom_need", 0.0))),
            "last_load_reduction": max(0.0, min(1.0, _num(item, "last_load_reduction", 0.0))),
            "uncertain_form_exposure": max(0.0, min(1.0, _num(item, "uncertain_form_exposure", 0.0))),
            "uncertainty_familiarity": max(0.0, min(1.0, _num(item, "uncertainty_familiarity", 0.0))),
            "variant_similarity": max(0.0, min(1.0, _num(item, "variant_similarity", 0.0))),
            "variant_spread": max(0.0, min(1.0, _num(item, "variant_spread", 0.0))),
            "variant_learning_pressure": max(0.0, min(1.0, _num(item, "variant_learning_pressure", 0.0))),
            "variant_bearing_memory": max(0.0, min(1.0, _num(item, "variant_bearing_memory", 0.0))),
            "uncertain_form_family_state": str(item.get("uncertain_form_family_state", "quiet_form_family") or "quiet_form_family"),
            "first_seen_ts": item.get("first_seen_ts", None),
            "last_seen_ts": item.get("last_seen_ts", None),
            "variants": dict(cleaned_variants or {}),
        }
        score = (float(cleaned.get("seen", 0) or 0) * 1.0) + (float(cleaned.get("resonance", 0.0) or 0.0) * 32.0)
        candidates.append((score, symbol_key, cleaned))

    for _, symbol_key, cleaned in sorted(candidates, reverse=True)[:max_symbols]:
        normalized[str(symbol_key)] = dict(cleaned or {})

    return normalized

def _normalize_form_symbol_memory_compounds(compounds):

    if not isinstance(compounds, dict):
        return {}

    normalized = {}
    max_compounds = max(16, int(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_MAX_COMPOUNDS", 768) or 768))

    def _num(item, key, default=0.0):
        try:
            return float((item or {}).get(key, default) or default)
        except Exception:
            return float(default)

    candidates = []
    for compound_id, raw_item in dict(compounds or {}).items():
        if not isinstance(raw_item, dict):
            continue

        compound_key = str(compound_id or raw_item.get("compound_id", "") or "").strip()
        if not compound_key:
            continue

        item = dict(raw_item or {})
        seen = max(0, int(_num(item, "seen", 0)))
        cleaned = {
            "compound_id": str(compound_key),
            "compound_key": str(item.get("compound_key", "") or ""),
            "left_symbol_id": str(item.get("left_symbol_id", "") or ""),
            "right_symbol_id": str(item.get("right_symbol_id", "") or ""),
            "scope": str(item.get("scope", "") or ""),
            "seen": int(seen),
            "maturity": max(0.0, min(1.0, _num(item, "maturity", 0.0))),
            "stability": max(0.0, min(1.0, _num(item, "stability", 0.0))),
            "resonance": max(0.0, min(1.0, _num(item, "resonance", 0.0))),
            "bearing": max(0.0, min(1.0, _num(item, "bearing", 0.0))),
            "load_reduction": max(0.0, min(1.0, _num(item, "load_reduction", 0.0))),
            "novelty": max(0.0, min(1.0, _num(item, "novelty", 0.0))),
            "development_quality": max(-1.0, min(1.0, _num(item, "development_quality", 0.0))),
            "action_affinity": max(0.0, min(1.0, _num(item, "action_affinity", 0.50))),
            "observation_affinity": max(0.0, min(1.0, _num(item, "observation_affinity", 0.0))),
            "context_reframe_potential": max(0.0, min(1.0, _num(item, "context_reframe_potential", 0.0))),
            "learning_trust": max(0.0, min(1.0, _num(item, "learning_trust", 0.0))),
            "action_trust": max(0.0, min(1.0, _num(item, "action_trust", 0.0))),
            "caution_trust": max(0.0, min(1.0, _num(item, "caution_trust", 0.0))),
            "contact_maturity": max(0.0, min(1.0, _num(item, "contact_maturity", 0.0))),
            "contact_utility": max(0.0, min(1.0, _num(item, "contact_utility", 0.0))),
            "contact_pain_memory": max(0.0, min(1.0, _num(item, "contact_pain_memory", 0.0))),
            "contact_carefulness": max(0.0, min(1.0, _num(item, "contact_carefulness", 0.0))),
            "contact_burden_evidence": max(0.0, min(1.0, _num(item, "contact_burden_evidence", 0.0))),
            "contact_utility_evidence": max(0.0, min(1.0, _num(item, "contact_utility_evidence", 0.0))),
            "contact_learning_state": str(item.get("contact_learning_state", "unformed_contact") or "unformed_contact"),
            "constructive_seen": max(0, int(_num(item, "constructive_seen", 0))),
            "unconstructive_seen": max(0, int(_num(item, "unconstructive_seen", 0))),
            "first_seen_ts": item.get("first_seen_ts", None),
            "last_seen_ts": item.get("last_seen_ts", None),
        }
        score = (float(seen) * 1.0) + (float(cleaned.get("resonance", 0.0) or 0.0) * 28.0)
        candidates.append((score, compound_key, cleaned))

    for _, compound_key, cleaned in sorted(candidates, reverse=True)[:max_compounds]:
        normalized[str(compound_key)] = dict(cleaned or {})

    return normalized

def _read_form_symbol_memory(path=None):

    filepath = _form_symbol_memory_path(path)
    default_payload = {
        "version": 1,
        "symbols": {},
        "compounds": {},
        "summary": {
            "symbol_count": 0,
            "compound_count": 0,
            "total_seen": 0,
            "compound_total_seen": 0,
        },
    }

    if not bool(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_ENABLED", True)):
        return dict(default_payload)

    if not os.path.exists(filepath):
        return dict(default_payload)

    try:
        with open(filepath, "r", encoding="utf-8") as handle:
            raw = json.load(handle)
    except Exception:
        return dict(default_payload)

    symbols = _normalize_form_symbol_memory_symbols((raw or {}).get("symbols", {}))
    compounds = _normalize_form_symbol_memory_compounds((raw or {}).get("compounds", {}))
    total_seen = sum(int((item or {}).get("seen", 0) or 0) for item in symbols.values())
    compound_total_seen = sum(int((item or {}).get("seen", 0) or 0) for item in compounds.values())
    return {
        "version": 1,
        "symbols": dict(symbols or {}),
        "compounds": dict(compounds or {}),
        "summary": {
            "symbol_count": int(len(symbols or {})),
            "compound_count": int(len(compounds or {})),
            "total_seen": int(total_seen),
            "compound_total_seen": int(compound_total_seen),
            "loaded_from": str(filepath),
            "last_saved_ts": (raw or {}).get("summary", {}).get("last_saved_ts", None) if isinstance((raw or {}).get("summary", {}), dict) else None,
        },
    }

def _ensure_form_symbol_memory_loaded(bot):

    if bot is None:
        return {}

    if bool(getattr(bot, "_form_symbol_memory_loaded", False)):
        return dict(getattr(bot, "form_symbol_space", {}) or {})

    payload = _read_form_symbol_memory()
    symbols = dict(payload.get("symbols", {}) or {})
    compounds = dict(payload.get("compounds", {}) or {})
    current = dict(getattr(bot, "form_symbol_space", {}) or {})
    current.update(symbols)
    bot.form_symbol_space = dict(current or {})
    compound_current = dict(getattr(bot, "form_symbol_compound_space", {}) or {})
    compound_current.update(compounds)
    bot.form_symbol_compound_space = dict(compound_current or {})
    bot._form_symbol_memory_loaded = True
    bot._form_symbol_memory_dirty = False
    bot._form_symbol_memory_updates = 0
    bot._form_symbol_memory_last_save_ts = float(time.time())
    bot.form_symbol_memory_summary = dict(payload.get("summary", {}) or {})
    return dict(bot.form_symbol_space or {})

def _write_text_atomic_with_retry(filepath, text, operation="atomic_write", extra=None, attempts=6, sleep_seconds=0.08):
    directory = os.path.dirname(filepath)
    if directory:
        os.makedirs(directory, exist_ok=True)

    payload = str(text or "")
    encoded_len = len(payload.encode("utf-8"))
    last_error = None
    write_start = time.perf_counter()

    for attempt in range(max(1, int(attempts or 1))):
        temp_path = f"{filepath}.{os.getpid()}.{int(time.time() * 1000)}.{attempt}.tmp"
        try:
            with open(temp_path, "w", encoding="utf-8") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, filepath)
            elapsed_ms = (time.perf_counter() - write_start) * 1000.0
            dbr_file_write_profile(
                filepath,
                elapsed_ms,
                bytes_written=encoded_len,
                operation=operation,
                extra=extra,
            )
            return True
        except PermissionError as exc:
            last_error = exc
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except Exception:
                pass
            time.sleep(max(0.0, float(sleep_seconds or 0.0)) * float(attempt + 1))
        except Exception as exc:
            last_error = exc
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except Exception:
                pass
            break

    try:
        dbr_append_text(
            dbr_path("memory_write_errors.log"),
            (
                f"{time.time():.6f};{operation};{str(filepath).replace(';', '|')};"
                f"{type(last_error).__name__ if last_error else 'UnknownError'};"
                f"{str(last_error).replace(';', '|') if last_error else ''}\n"
            ),
            operation="memory_write_error",
        )
    except Exception:
        pass
    return False

def _write_form_symbol_memory(bot, force=False):

    if bot is None or not bool(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_ENABLED", True)):
        return None

    if not bool(force) and not bool(getattr(bot, "_form_symbol_memory_dirty", False)):
        return None

    symbols = _normalize_form_symbol_memory_symbols(getattr(bot, "form_symbol_space", {}) or {})
    compounds = _normalize_form_symbol_memory_compounds(getattr(bot, "form_symbol_compound_space", {}) or {})
    total_seen = sum(int((item or {}).get("seen", 0) or 0) for item in symbols.values())
    compound_total_seen = sum(int((item or {}).get("seen", 0) or 0) for item in compounds.values())
    filepath = _form_symbol_memory_path()
    payload = {
        "version": 1,
        "summary": {
            "symbol_count": int(len(symbols or {})),
            "compound_count": int(len(compounds or {})),
            "total_seen": int(total_seen),
            "compound_total_seen": int(compound_total_seen),
            "last_saved_ts": float(time.time()),
        },
        "symbols": dict(symbols or {}),
        "compounds": dict(compounds or {}),
    }

    text = json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True)
    written = _write_text_atomic_with_retry(
        filepath,
        text,
        operation="form_symbol_memory_write",
        extra=f"symbols={int(len(symbols or {}))}|total_seen={int(total_seen)}",
    )
    if not written:
        bot._form_symbol_memory_dirty = True
        return None

    bot.form_symbol_space = dict(symbols or {})
    bot.form_symbol_compound_space = dict(compounds or {})
    bot.form_symbol_memory_summary = dict(payload.get("summary", {}) or {})
    bot._form_symbol_memory_dirty = False
    bot._form_symbol_memory_last_save_ts = float(time.time())
    return dict(payload or {})

def _flush_form_symbol_memory_if_due(bot, force=False):

    if bot is None or not bool(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_ENABLED", True)):
        return None

    if not bool(force) and not bool(getattr(bot, "_form_symbol_memory_dirty", False)):
        return None

    updates = int(getattr(bot, "_form_symbol_memory_updates", 0) or 0)
    every_n = max(1, int(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_SAVE_EVERY_N", 64) or 64))
    if not bool(force) and updates % every_n != 0:
        return None

    return _write_form_symbol_memory(bot, force=True)

def _extract_outcome_form_symbol_state(bot, position=None):

    position_state = dict(position or {}) if isinstance(position, dict) else {}
    meta = dict(position_state.get("meta", {}) or {}) if isinstance(position_state.get("meta", {}), dict) else {}

    for candidate in (
        meta.get("form_symbol_state", {}),
        (meta.get("runtime_result", {}) or {}).get("form_symbol_state", {}) if isinstance(meta.get("runtime_result", {}), dict) else {},
        (meta.get("brain_snapshot", {}) or {}).get("form_symbol_state", {}) if isinstance(meta.get("brain_snapshot", {}), dict) else {},
        getattr(bot, "form_symbol_state", {}) if bot is not None else {},
    ):
        if not isinstance(candidate, dict):
            continue
        symbol_id = str(candidate.get("form_symbol_id", "") or "").strip()
        if symbol_id and symbol_id != "-":
            return dict(candidate or {})

    return {}

def _update_form_symbol_development_from_outcome(bot, outcome_reason, position=None, outcome_decomposition=None):

    if bot is None or not bool(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_ENABLED", True)):
        return {}

    _ensure_form_symbol_memory_loaded(bot)

    form_state = _extract_outcome_form_symbol_state(bot, position=position)
    symbol_id = str(form_state.get("form_symbol_id", "") or "").strip()
    if not symbol_id or symbol_id == "-":
        return {}

    outcome = dict(outcome_decomposition or {})
    reason = str(outcome_reason or outcome.get("reason", "") or "").strip().lower()

    def _b01(value, default=0.0):
        try:
            return max(0.0, min(1.0, float(value)))
        except Exception:
            return float(default)

    def _bs(value, default=0.0):
        try:
            return max(-1.0, min(1.0, float(value)))
        except Exception:
            return float(default)

    structure_quality = _b01(form_state.get("form_symbol_bearing", 0.0))
    meta = dict((position or {}).get("meta", {}) or {}) if isinstance(position, dict) else {}
    bearing_context = dict(meta.get("bearing_context", {}) or {}) if isinstance(meta.get("bearing_context", {}), dict) else {}
    if bearing_context:
        structure_quality = _b01(bearing_context.get("structure_quality", structure_quality))
    contact_state = dict(meta.get("active_mcm_contact_state", meta.get("active_mcm_contact", {})) or {}) if isinstance(meta, dict) else {}
    meta_regulation = dict(meta.get("meta_regulation_state", {}) or {}) if isinstance(meta.get("meta_regulation_state", {}), dict) else {}
    if not contact_state and meta_regulation:
        contact_state = dict(meta_regulation.get("active_mcm_contact", {}) or {})
    contact_action_maturity = _b01(contact_state.get("contact_action_maturity", 0.0))
    contact_carrying_quality = _b01(contact_state.get("contact_carrying_quality", 0.0))
    contact_reality_check = _b01(contact_state.get("contact_reality_check", 0.0))
    contact_temporal_bearing = _b01(contact_state.get("contact_temporal_bearing", meta_regulation.get("contact_temporal_bearing", 0.0)))
    contact_overcoupling_risk = _b01(contact_state.get("contact_overcoupling_risk", 0.0))
    contact_learning_need = _b01(contact_state.get("contact_learning_need", 0.0))
    contact_context_reframe_need = _b01(contact_state.get("contact_context_reframe_need", 0.0))
    contact_regime_mismatch = _b01(contact_state.get("contact_regime_mismatch", 0.0))
    area_bearing_quality = _b01(meta_regulation.get("area_bearing_quality", meta.get("area_bearing_quality", 0.0)) if isinstance(meta, dict) else 0.0)
    area_spacetime_fit = _b01(meta_regulation.get("area_spacetime_fit", meta.get("area_spacetime_fit", 0.0)) if isinstance(meta, dict) else 0.0)
    position_intervention_state = dict(meta.get("position_intervention_state", {}) or {}) if isinstance(meta, dict) else {}
    position_experience_state = dict(position_intervention_state.get("position_experience_state", {}) or {})
    position_experience_label = str(
        position_intervention_state.get(
            "position_experience_label",
            position_experience_state.get("position_experience_label", "-"),
        )
        or "-"
    ).strip().lower()
    position_inconsistency_stress = _b01(position_intervention_state.get("position_inconsistency_stress", position_experience_state.get("position_inconsistency_stress", 0.0)))
    position_mcm_field_strain = _b01(position_intervention_state.get("position_mcm_field_strain", position_experience_state.get("position_mcm_field_strain", 0.0)))
    position_self_trust_gap = _b01(position_intervention_state.get("position_self_trust_gap", position_experience_state.get("position_self_trust_gap", 0.0)))
    position_cortisol_load = _b01(position_intervention_state.get("position_cortisol_load", position_experience_state.get("position_cortisol_load", 0.0)))
    position_noradrenaline_arousal = _b01(position_intervention_state.get("position_noradrenaline_arousal", position_experience_state.get("position_noradrenaline_arousal", 0.0)))
    position_protective_distance = _b01(position_intervention_state.get("position_protective_distance", position_experience_state.get("position_protective_distance", 0.0)))
    position_held_risk_discomfort = _b01(position_intervention_state.get("position_held_risk_discomfort", position_experience_state.get("position_held_risk_discomfort", 0.0)))
    position_process_quality = _b01(position_intervention_state.get("position_process_quality", position_experience_state.get("position_process_quality", 0.50)), default=0.50)

    position_consequence_burden = _b01(
        (position_held_risk_discomfort * 0.26)
        + (position_inconsistency_stress * 0.22)
        + (position_cortisol_load * 0.18)
        + (position_self_trust_gap * 0.14)
        + (position_mcm_field_strain * 0.10)
        + (position_noradrenaline_arousal * 0.06)
        + ((1.0 - position_process_quality) * 0.04)
    )
    if position_experience_label == "protective_stress_contact":
        position_consequence_burden = _b01(position_consequence_burden + 0.10)
    elif position_experience_label == "self_trust_gap_contact":
        position_consequence_burden = _b01(position_consequence_burden + 0.06)
    elif position_experience_label == "unearned_relief_watch":
        position_consequence_burden = _b01(position_consequence_burden + 0.05)

    position_constructive_bearing = _b01(
        (position_process_quality * 0.34)
        + ((1.0 - position_inconsistency_stress) * 0.16)
        + ((1.0 - position_held_risk_discomfort) * 0.14)
        + ((1.0 - position_mcm_field_strain) * 0.12)
        + (max(0.0, 1.0 - position_self_trust_gap) * 0.10)
        + (contact_action_maturity * 0.08)
        + (contact_reality_check * 0.06)
    )
    if position_experience_label == "carried_position_contact":
        position_constructive_bearing = _b01(position_constructive_bearing + 0.10)

    emotional_decoupling = _b01(meta.get("emotional_decoupling", 0.0))
    if not emotional_decoupling and isinstance(meta.get("meta_regulation_state", {}), dict):
        emotional_decoupling = _b01((meta.get("meta_regulation_state", {}) or {}).get("emotional_decoupling", 0.0))

    process_quality = _b01(
        (
            _b01(outcome.get("perception_quality", 0.50)) * 0.18
            + _b01(outcome.get("felt_quality", 0.50)) * 0.16
            + _b01(outcome.get("thought_quality", 0.50)) * 0.18
            + _b01(outcome.get("plan_quality", 0.50)) * 0.22
            + _b01(outcome.get("execution_quality", 0.50)) * 0.14
            + _b01(outcome.get("risk_fit_quality", 0.50)) * 0.12
        ),
        default=0.50,
    )
    if position_intervention_state:
        process_quality = _b01(
            (process_quality * 0.74)
            + (position_process_quality * 0.20)
            + (position_constructive_bearing * 0.08)
            - (position_consequence_burden * 0.10),
            default=process_quality,
        )
    context_quality = _b01(outcome.get("context_quality", 0.0))
    risk_width_pressure = _b01(outcome.get("risk_width_pressure", 0.0))
    structural_support = _b01((structure_quality * 0.64) + (context_quality * 0.36))
    constructive_signal = _b01((process_quality * 0.62) + (structural_support * 0.38))
    outcome_contact_reward = 0.40
    result_bias = 0.0
    if reason == "tp_hit":
        result_bias = 0.18
        outcome_contact_reward = 0.72
    elif reason == "sl_hit":
        result_bias = -0.22 - (max(0.0, 0.56 - structure_quality) * 0.22) - (risk_width_pressure * 0.12)
        outcome_contact_reward = 0.18
    elif reason in ("cancel", "timeout"):
        result_bias = -0.08
        outcome_contact_reward = 0.34
    elif reason in ("reward_too_small", "rr_too_low", "sl_distance_too_high"):
        result_bias = -0.12
        outcome_contact_reward = 0.28

    development_sample = _bs(((constructive_signal - 0.50) * 1.40) + result_bias)
    transitional_contact_band = _b01(1.0 - min(1.0, abs(structure_quality - 0.54) / 0.24))
    transitional_contact_maturation = _b01(
        (transitional_contact_band * 0.18)
        + (contact_temporal_bearing * 0.18)
        + (area_bearing_quality * 0.16)
        + (area_spacetime_fit * 0.12)
        + (contact_reality_check * 0.16)
        + (position_constructive_bearing * 0.16)
        - (position_consequence_burden * 0.14)
        - (contact_overcoupling_risk * 0.08)
    )
    transitional_contact_maturation = max(0.0, transitional_contact_maturation - 0.30)
    contact_utility_sample = _b01(
        (process_quality * 0.26)
        + (structural_support * 0.20)
        + (outcome_contact_reward * 0.20)
        + (contact_carrying_quality * 0.12)
        + (contact_action_maturity * 0.10)
        + (contact_reality_check * 0.08)
        + (emotional_decoupling * 0.04)
        + (position_constructive_bearing * 0.08)
        + (transitional_contact_maturation * 0.08)
        - (contact_overcoupling_risk * 0.12)
        - (risk_width_pressure * 0.08)
        - (position_consequence_burden * 0.10)
    )
    contact_pain_sample = _b01(
        ((0.52 if reason == "sl_hit" else 0.08) * 0.34)
        + (risk_width_pressure * 0.18)
        + (contact_overcoupling_risk * 0.16)
        + (max(0.0, 0.48 - process_quality) * 0.16)
        + (max(0.0, 0.50 - structural_support) * 0.14)
        + (contact_regime_mismatch * 0.08)
        + (position_consequence_burden * 0.18)
        - (contact_reality_check * 0.08)
        - (emotional_decoupling * 0.06)
        - (position_constructive_bearing * 0.05)
    )
    position_consequence_residual_for_care = _b01(
        position_consequence_burden * (1.0 - min(0.72, contact_pain_sample * 1.35))
    )
    contact_maturity_sample = _b01(
        (contact_utility_sample * 0.36)
        + (contact_action_maturity * 0.18)
        + (contact_reality_check * 0.14)
        + (structural_support * 0.12)
        + (process_quality * 0.10)
        + (emotional_decoupling * 0.10)
        + (position_constructive_bearing * 0.08)
        + (transitional_contact_maturation * 0.10)
        - (contact_pain_sample * 0.20)
        - (position_consequence_burden * 0.06)
    )
    contact_carefulness_sample = _b01(
        (contact_pain_sample * 0.38)
        + (contact_learning_need * 0.20)
        + (contact_context_reframe_need * 0.16)
        + (contact_regime_mismatch * 0.12)
        + (max(0.0, 0.46 - contact_maturity_sample) * 0.14)
        + (position_consequence_residual_for_care * 0.16)
        + (position_protective_distance * 0.08)
    )
    position_consequence_residual_for_memory = _b01(
        position_consequence_burden
        * (1.0 - min(0.78, (contact_pain_sample * 0.95) + (contact_carefulness_sample * 0.65)))
    )
    contact_learning_state = "unformed_contact"
    if contact_pain_sample >= 0.30 and contact_maturity_sample < 0.30:
        contact_learning_state = "burdened_contact"
    elif contact_carefulness_sample >= 0.22 and contact_pain_sample >= 0.20 and contact_maturity_sample < 0.38:
        contact_learning_state = "careful_contact"
    elif contact_utility_sample >= 0.40 and contact_maturity_sample >= 0.32:
        contact_learning_state = "constructive_contact"
    elif contact_learning_need >= 0.30 or contact_context_reframe_need >= 0.28:
        contact_learning_state = "learning_contact"
    elif contact_maturity_sample >= 0.30:
        contact_learning_state = "maturing_contact"
    if position_consequence_burden >= 0.48 and contact_maturity_sample < 0.42:
        contact_learning_state = "protective_reorganization_contact"
    elif position_experience_label == "unearned_relief_watch" and contact_maturity_sample < 0.46:
        contact_learning_state = "careful_contact"
    observation_sample = _b01(
        max(0.0, -development_sample) * 0.54
        + max(0.0, 0.52 - structural_support) * 0.34
        + max(0.0, 0.46 - process_quality) * 0.20
        + (risk_width_pressure * 0.12 if reason == "sl_hit" else 0.0)
        + (contact_carefulness_sample * 0.10)
    )
    reframe_sample = _b01(
        observation_sample * 0.46
        + _b01(form_state.get("form_symbol_novelty", 0.0)) * 0.14
        + _b01(form_state.get("form_symbol_compound_novelty", 0.0)) * 0.12
        + max(0.0, 0.50 - structure_quality) * 0.28
        + (contact_context_reframe_need * 0.08)
    )

    def _learn_item(item, weight=1.0):
        learned = dict(item or {})
        prior_quality = _bs(learned.get("development_quality", 0.0))
        prior_action = _b01(learned.get("action_affinity", 0.50), default=0.50)
        prior_observe = _b01(learned.get("observation_affinity", 0.0))
        prior_reframe = _b01(learned.get("context_reframe_potential", 0.0))
        prior_contact_maturity = _b01(learned.get("contact_maturity", 0.0))
        prior_contact_utility = _b01(learned.get("contact_utility", 0.0))
        prior_contact_pain = _b01(learned.get("contact_pain_memory", 0.0))
        prior_contact_carefulness = _b01(learned.get("contact_carefulness", 0.0))
        prior_contact_burden_evidence = _b01(learned.get("contact_burden_evidence", 0.0))
        prior_contact_utility_evidence = _b01(learned.get("contact_utility_evidence", 0.0))
        sample = _bs(development_sample * float(weight))
        quality_alpha = 0.12 if abs(sample) < 0.18 else 0.17
        next_quality = _bs((prior_quality * (1.0 - quality_alpha)) + (sample * quality_alpha))
        contact_alpha = 0.12 if contact_pain_sample < 0.32 else 0.18
        next_contact_maturity = _b01((prior_contact_maturity * (1.0 - contact_alpha)) + (contact_maturity_sample * contact_alpha))
        next_contact_utility = _b01((prior_contact_utility * 0.86) + (contact_utility_sample * 0.14))
        next_contact_pain = _b01((prior_contact_pain * (1.0 - contact_alpha)) + (contact_pain_sample * contact_alpha))
        next_contact_carefulness = _b01((prior_contact_carefulness * 0.82) + (contact_carefulness_sample * 0.18))
        contact_burden_signal = _b01(
            (contact_pain_sample * 0.46)
            + (contact_carefulness_sample * 0.28)
            + (risk_width_pressure * 0.12 if reason == "sl_hit" else 0.0)
            + (max(0.0, -development_sample) * 0.14)
            + (position_consequence_residual_for_memory * 0.14)
        )
        contact_utility_signal = _b01(
            (contact_utility_sample * 0.42)
            + (contact_maturity_sample * 0.26)
            + (max(0.0, development_sample) * 0.18)
            + (structural_support * 0.14)
            + (position_constructive_bearing * 0.08)
            - (position_consequence_burden * 0.06)
        )
        burden_alpha = 0.24 if development_sample < -0.08 or reason == "sl_hit" else 0.14
        utility_alpha = 0.20 if development_sample >= 0.0 else 0.12
        next_contact_burden_evidence = _b01((prior_contact_burden_evidence * (1.0 - burden_alpha)) + (contact_burden_signal * burden_alpha))
        next_contact_utility_evidence = _b01((prior_contact_utility_evidence * (1.0 - utility_alpha)) + (contact_utility_signal * utility_alpha))
        action_target = _b01(
            0.47
            + (next_quality * 0.50)
            + ((structural_support - 0.50) * 0.26)
            + (next_contact_maturity * 0.15)
            + (next_contact_utility * 0.10)
            + (next_contact_utility_evidence * 0.05)
            - (observation_sample * 0.10)
            - (next_contact_pain * 0.14)
            - (next_contact_carefulness * 0.07)
            - (next_contact_burden_evidence * 0.06)
            - (risk_width_pressure * 0.12 if reason == "sl_hit" else 0.0),
            default=0.50,
        )
        observe_target = _b01(
            (observation_sample * 0.64)
            + (max(0.0, -next_quality) * 0.28)
            + (risk_width_pressure * 0.12 if reason == "sl_hit" else 0.0)
            + (next_contact_carefulness * 0.14)
            + (next_contact_burden_evidence * 0.08)
        )
        reframe_target = _b01((reframe_sample * 0.62) + (prior_reframe * 0.22) + (next_contact_carefulness * 0.10) + (next_contact_burden_evidence * 0.06))
        constructive_seen = int(learned.get("constructive_seen", 0) or 0)
        unconstructive_seen = int(learned.get("unconstructive_seen", 0) or 0)
        evidence_count = constructive_seen + unconstructive_seen + 1
        evidence_trust = _b01(evidence_count / float(evidence_count + 10))
        consistency_trust = _b01(abs(next_quality) * 1.45)
        caution_evidence_bias = _b01((unconstructive_seen + (1 if development_sample < 0.0 else 0)) / float(evidence_count + 2))
        action_evidence_bias = _b01((constructive_seen + (1 if development_sample >= 0.0 else 0)) / float(evidence_count + 2))
        learning_target = _b01((evidence_trust * 0.58) + (consistency_trust * 0.42))
        learned["development_quality"] = float(next_quality)
        plasticity = 0.18 if development_sample < -0.08 else 0.13
        learned["action_affinity"] = float(_b01((prior_action * (1.0 - plasticity)) + (action_target * plasticity), default=0.50))
        learned["observation_affinity"] = float(_b01((prior_observe * 0.80) + (observe_target * 0.20)))
        learned["context_reframe_potential"] = float(_b01((prior_reframe * 0.84) + (reframe_target * 0.16)))
        learned["contact_maturity"] = float(next_contact_maturity)
        learned["contact_utility"] = float(next_contact_utility)
        learned["contact_pain_memory"] = float(next_contact_pain)
        learned["contact_carefulness"] = float(next_contact_carefulness)
        learned["contact_burden_evidence"] = float(next_contact_burden_evidence)
        learned["contact_utility_evidence"] = float(next_contact_utility_evidence)
        stored_contact_state = str(contact_learning_state)
        if contact_learning_state == "protective_reorganization_contact" and next_contact_maturity < 0.44:
            stored_contact_state = "protective_reorganization_contact"
        elif next_contact_burden_evidence >= 0.16 and next_contact_carefulness >= 0.06 and next_contact_maturity < 0.20:
            stored_contact_state = "careful_contact"
        elif next_contact_pain >= 0.09 and next_contact_maturity < 0.16 and next_quality < -0.04:
            stored_contact_state = "burdened_contact"
        elif next_contact_utility_evidence >= 0.16 and next_contact_utility >= 0.10 and next_contact_maturity >= 0.08 and next_contact_pain < 0.13:
            stored_contact_state = "constructive_contact" if next_contact_maturity >= 0.16 else "maturing_contact"
        elif next_contact_burden_evidence >= 0.10 or next_contact_carefulness >= 0.08:
            stored_contact_state = "learning_contact"
        elif next_contact_maturity >= 0.10:
            stored_contact_state = "maturing_contact"
        learned["contact_learning_state"] = str(stored_contact_state)
        if development_sample >= 0.0:
            learned["constructive_seen"] = int(learned.get("constructive_seen", 0) or 0) + 1
        else:
            learned["unconstructive_seen"] = int(learned.get("unconstructive_seen", 0) or 0) + 1
        prior_learning_trust = _b01(learned.get("learning_trust", 0.0))
        prior_action_trust = _b01(learned.get("action_trust", 0.0))
        prior_caution_trust = _b01(learned.get("caution_trust", 0.0))
        action_trust_target = _b01(
            (
                (max(0.0, next_quality) * 0.72)
                + (action_evidence_bias * max(0.0, structural_support - 0.45) * 0.28)
            )
            * learning_target
            * (0.55 + structural_support * 0.45)
        )
        caution_trust_target = _b01(
            (
                (max(0.0, -next_quality) * 0.56)
                + (caution_evidence_bias * 0.30)
                + (risk_width_pressure * 0.14 if reason == "sl_hit" else 0.0)
                + (next_contact_pain * 0.16)
                + (next_contact_carefulness * 0.10)
                + (next_contact_burden_evidence * 0.08)
            )
            * learning_target
            * (0.62 + observation_sample * 0.38)
        )
        learned["learning_trust"] = float(_b01((prior_learning_trust * 0.82) + (learning_target * 0.18)))
        learned["action_trust"] = float(_b01((prior_action_trust * 0.84) + (action_trust_target * 0.16)))
        caution_alpha = 0.30 if development_sample < -0.08 else 0.22
        learned["caution_trust"] = float(_b01((prior_caution_trust * (1.0 - caution_alpha)) + (caution_trust_target * caution_alpha)))
        learned["last_development_reason"] = str(reason or "-")
        learned["last_development_sample"] = float(development_sample)
        learned["last_contact_maturity_sample"] = float(contact_maturity_sample)
        learned["last_contact_utility_sample"] = float(contact_utility_sample)
        learned["last_contact_pain_sample"] = float(contact_pain_sample)
        learned["last_contact_carefulness_sample"] = float(contact_carefulness_sample)
        learned["last_development_ts"] = getattr(bot, "current_timestamp", None)
        return learned

    symbol_space = dict(getattr(bot, "form_symbol_space", {}) or {})
    symbol_item = _learn_item(dict(symbol_space.get(symbol_id, {}) or {}), weight=1.0)
    symbol_space[str(symbol_id)] = dict(symbol_item)
    bot.form_symbol_space = dict(symbol_space)

    compound_id = str(form_state.get("form_symbol_compound_id", "") or "").strip()
    compound_item = {}
    if compound_id and compound_id != "-":
        compound_space = dict(getattr(bot, "form_symbol_compound_space", {}) or {})
        compound_item = _learn_item(dict(compound_space.get(compound_id, {}) or {}), weight=0.86)
        compound_space[str(compound_id)] = dict(compound_item)
        bot.form_symbol_compound_space = dict(compound_space)

    bot._form_symbol_memory_dirty = True
    bot._form_symbol_memory_updates = int(getattr(bot, "_form_symbol_memory_updates", 0) or 0) + 1
    _flush_form_symbol_memory_if_due(bot, force=True)

    return {
        "symbol_id": str(symbol_id),
        "compound_id": str(compound_id or "-"),
        "development_sample": float(development_sample),
        "process_quality": float(process_quality),
        "structural_support": float(structural_support),
        "risk_width_pressure": float(risk_width_pressure),
        "symbol_development_quality": float(symbol_item.get("development_quality", 0.0) or 0.0),
        "symbol_action_affinity": float(symbol_item.get("action_affinity", 0.50) or 0.50),
        "symbol_observation_affinity": float(symbol_item.get("observation_affinity", 0.0) or 0.0),
        "symbol_reframe_potential": float(symbol_item.get("context_reframe_potential", 0.0) or 0.0),
        "symbol_contact_maturity": float(symbol_item.get("contact_maturity", 0.0) or 0.0),
        "symbol_contact_utility": float(symbol_item.get("contact_utility", 0.0) or 0.0),
        "symbol_contact_pain_memory": float(symbol_item.get("contact_pain_memory", 0.0) or 0.0),
        "symbol_contact_carefulness": float(symbol_item.get("contact_carefulness", 0.0) or 0.0),
        "symbol_contact_burden_evidence": float(symbol_item.get("contact_burden_evidence", 0.0) or 0.0),
        "symbol_contact_utility_evidence": float(symbol_item.get("contact_utility_evidence", 0.0) or 0.0),
        "symbol_contact_learning_state": str(symbol_item.get("contact_learning_state", contact_learning_state) or contact_learning_state),
        "contact_maturity_sample": float(contact_maturity_sample),
        "contact_utility_sample": float(contact_utility_sample),
        "contact_pain_sample": float(contact_pain_sample),
        "contact_carefulness_sample": float(contact_carefulness_sample),
        "contact_learning_state": str(contact_learning_state),
        "position_consequence_burden": float(position_consequence_burden),
        "position_consequence_residual_for_care": float(position_consequence_residual_for_care),
        "position_consequence_residual_for_memory": float(position_consequence_residual_for_memory),
        "position_constructive_bearing": float(position_constructive_bearing),
        "transitional_contact_band": float(transitional_contact_band),
        "transitional_contact_maturation": float(transitional_contact_maturation),
        "position_feedback_label": str(position_experience_label or "-"),
        "position_process_quality": float(position_process_quality),
        "position_held_risk_discomfort": float(position_held_risk_discomfort),
        "position_cortisol_load": float(position_cortisol_load),
        "position_noradrenaline_arousal": float(position_noradrenaline_arousal),
        "compound_development_quality": float(compound_item.get("development_quality", 0.0) or 0.0) if compound_item else 0.0,
        "compound_contact_maturity": float(compound_item.get("contact_maturity", 0.0) or 0.0) if compound_item else 0.0,
        "compound_contact_burden_evidence": float(compound_item.get("contact_burden_evidence", 0.0) or 0.0) if compound_item else 0.0,
        "compound_contact_utility_evidence": float(compound_item.get("contact_utility_evidence", 0.0) or 0.0) if compound_item else 0.0,
    }

def build_form_symbol_state(bot, visual_market_state=None, structure_perception_state=None, perception_state=None, felt_state=None, snapshot=None):

    visual = dict(visual_market_state or {})
    structure = dict(structure_perception_state or {})
    perception = dict(perception_state or {})
    felt = dict(felt_state or {})
    snap = dict(snapshot or {})

    if not isinstance(getattr(bot, "form_symbol_space", None), dict):
        if bot is not None:
            bot.form_symbol_space = {}
    if not isinstance(getattr(bot, "form_symbol_compound_space", None), dict):
        if bot is not None:
            bot.form_symbol_compound_space = {}

    if bot is not None:
        _ensure_form_symbol_memory_loaded(bot)

    spatial_bias = float(visual.get("spatial_bias", perception.get("spatial_bias", 0.0)) or 0.0)
    directional_bias = float(visual.get("directional_bias", perception.get("directional_bias", 0.0)) or 0.0)
    range_position = float(visual.get("range_position", perception.get("range_position", 0.0)) or 0.0)
    short_impulse = float(visual.get("short_impulse", 0.0) or 0.0)
    mid_impulse = float(visual.get("mid_impulse", 0.0) or 0.0)
    compression = float(visual.get("compression", 0.0) or 0.0)
    expansion = float(visual.get("expansion", 0.0) or 0.0)
    body_pressure = float(visual.get("body_pressure", 0.0) or 0.0)
    wick_pressure = float(visual.get("wick_pressure", 0.0) or 0.0)
    market_balance = float(visual.get("market_balance", perception.get("market_balance", 0.0)) or 0.0)
    breakout_tension = float(visual.get("breakout_tension", perception.get("breakout_tension", 0.0)) or 0.0)
    visual_coherence = float(visual.get("visual_coherence", perception.get("visual_coherence", 0.0)) or 0.0)
    visual_clarity = float(visual.get("visual_clarity", perception.get("visual_clarity", 0.0)) or 0.0)
    visual_object_stability = float(visual.get("visual_object_stability", perception.get("visual_object_stability", 0.0)) or 0.0)
    visual_form_novelty = float(visual.get("visual_form_novelty", perception.get("visual_form_novelty", 0.0)) or 0.0)
    visual_blindness = float(visual.get("visual_blindness", perception.get("visual_blindness", 0.0)) or 0.0)
    visual_form_pressure = float(visual.get("visual_form_pressure", perception.get("visual_form_pressure", 0.0)) or 0.0)
    visual_shape_resonance = float(visual.get("visual_shape_resonance", perception.get("visual_shape_resonance", 0.0)) or 0.0)
    visual_shape_fragility = float(visual.get("visual_shape_fragility", perception.get("visual_shape_fragility", 0.0)) or 0.0)
    structure_quality = float(structure.get("structure_quality", perception.get("structure_quality", felt.get("structure_quality", 0.0))) or 0.0)
    zone_proximity = float(structure.get("zone_proximity", perception.get("zone_proximity", 0.0)) or 0.0)
    context_confidence = float(structure.get("context_confidence", perception.get("context_confidence", felt.get("context_confidence", 0.0))) or 0.0)
    stress_relief_potential = float(structure.get("stress_relief_potential", perception.get("stress_relief_potential", felt.get("stress_relief_potential", 0.0))) or 0.0)
    field_clarity = float(felt.get("field_perception_clarity", snap.get("field_perception_clarity", 0.0)) or 0.0)
    field_pressure = float(felt.get("field_perception_pressure", snap.get("field_perception_pressure", 0.0)) or 0.0)
    field_fragmentation = float(felt.get("field_perception_fragmentation", snap.get("field_perception_fragmentation", 0.0)) or 0.0)

    form_vector = [
        _quantize_form_axis(spatial_bias),
        _quantize_form_axis(directional_bias),
        _quantize_form_axis(range_position),
        _quantize_form_axis(short_impulse),
        _quantize_form_axis(mid_impulse),
        _quantize_form_axis(compression),
        _quantize_form_axis(expansion),
        _quantize_form_axis(body_pressure),
        _quantize_form_axis(wick_pressure),
        _quantize_form_axis(market_balance),
        _quantize_form_axis(breakout_tension),
        _quantize_form_axis(visual_coherence),
        _quantize_form_axis(structure_quality),
        _quantize_form_axis(zone_proximity),
        _quantize_form_axis(context_confidence),
        _quantize_form_axis(stress_relief_potential),
        _quantize_form_axis(field_clarity),
        _quantize_form_axis(field_pressure),
        _quantize_form_axis(field_fragmentation),
    ]
    form_key = "|".join(f"{float(item):.2f}" for item in form_vector)

    form_resolution_quality = max(
        0.0,
        min(
            1.0,
            (visual_coherence * 0.20)
            + (structure_quality * 0.24)
            + (context_confidence * 0.22)
            + (field_clarity * 0.16)
            + (market_balance * 0.10)
            + (stress_relief_potential * 0.08)
            - (field_fragmentation * 0.18)
            - (field_pressure * 0.06),
        ),
    )
    form_detail_pressure = max(
        0.0,
        min(
            1.0,
            (abs(directional_bias) * 0.18)
            + (abs(range_position) * 0.12)
            + (abs(short_impulse - mid_impulse) * 0.12)
            + (breakout_tension * 0.18)
            + (((body_pressure + wick_pressure) * 0.50) * 0.16)
            + (field_pressure * 0.14)
            + (field_fragmentation * 0.10),
        ),
    )

    if form_resolution_quality < 0.34:
        form_symbol_scope = "wide_trace"
        form_symbol_abstraction_level = 0
        family_vector = [
            _quantize_form_axis((directional_bias + spatial_bias) * 0.50, step=0.75),
            _quantize_form_axis((short_impulse + mid_impulse) * 0.50, step=0.75),
            _quantize_form_axis((structure_quality + context_confidence) * 0.50, step=0.50, min_value=0.0, max_value=1.0),
            _quantize_form_axis((field_pressure + breakout_tension) * 0.50, step=0.50, min_value=0.0, max_value=1.0),
        ]
    elif form_resolution_quality < 0.58:
        form_symbol_scope = "wide_form"
        form_symbol_abstraction_level = 1
        family_vector = [
            _quantize_form_axis(directional_bias, step=0.55),
            _quantize_form_axis(range_position, step=0.55),
            _quantize_form_axis((short_impulse + mid_impulse) * 0.50, step=0.55),
            _quantize_form_axis(compression - expansion, step=0.55),
            _quantize_form_axis((body_pressure + wick_pressure) * 0.50, step=0.50),
            _quantize_form_axis((structure_quality + context_confidence + zone_proximity) / 3.0, step=0.50, min_value=0.0, max_value=1.0),
            _quantize_form_axis(field_clarity - ((field_pressure + field_fragmentation) * 0.50), step=0.50, min_value=-1.0, max_value=1.0),
        ]
    else:
        form_symbol_scope = "structured_form"
        form_symbol_abstraction_level = 2
        family_vector = [
            _quantize_form_axis(directional_bias, step=0.40),
            _quantize_form_axis(range_position, step=0.40),
            _quantize_form_axis((short_impulse + mid_impulse) * 0.50, step=0.40),
            _quantize_form_axis(compression - expansion, step=0.40),
            _quantize_form_axis((body_pressure + wick_pressure) * 0.50, step=0.40),
            _quantize_form_axis((structure_quality + context_confidence + zone_proximity) / 3.0, step=0.35, min_value=0.0, max_value=1.0),
            _quantize_form_axis((market_balance + visual_coherence - breakout_tension) / 2.0, step=0.35, min_value=-1.0, max_value=1.0),
            _quantize_form_axis(field_clarity - ((field_pressure + field_fragmentation) * 0.50), step=0.35, min_value=-1.0, max_value=1.0),
        ]

    family_key = str(form_symbol_abstraction_level) + "|" + "|".join(f"{float(item):.2f}" for item in family_vector)
    digest = hashlib.sha1(str(family_key).encode("utf-8")).hexdigest()[:10]
    symbol_id = f"fs_{digest}"

    symbol_space = dict(getattr(bot, "form_symbol_space", {}) or {}) if bot is not None else {}
    item = dict(symbol_space.get(symbol_id, {}) or {})
    seen_before = int(item.get("seen", 0) or 0)
    avg_vector = list(item.get("avg_vector", form_vector) or form_vector)
    if len(avg_vector) != len(form_vector):
        avg_vector = list(form_vector)

    current_vector = np.asarray(form_vector, dtype=float)
    prior_vector = np.asarray(avg_vector, dtype=float)
    distance = float(np.linalg.norm(current_vector - prior_vector) / max(1.0, len(form_vector) ** 0.5))
    seen = seen_before + 1
    alpha = min(0.35, 1.0 / max(1, seen))
    new_avg = ((prior_vector * (1.0 - alpha)) + (current_vector * alpha)).tolist()
    prior_variance = float(item.get("variance", 0.0) or 0.0)
    variance = max(0.0, min(1.0, (prior_variance * 0.92) + (distance * 0.08)))

    maturity = max(0.0, min(1.0, seen / float(seen + 8)))
    stability = max(0.0, min(1.0, 1.0 - (variance * 2.4)))
    novelty = max(0.0, min(1.0, 1.0 - maturity + min(1.0, distance)))
    relevance = max(
        0.0,
        min(
            1.0,
            (abs(directional_bias) * 0.16)
            + (breakout_tension * 0.16)
            + (abs(range_position) * 0.10)
            + (body_pressure * 0.12)
            + (wick_pressure * 0.12)
            + (field_pressure * 0.12)
            + (field_fragmentation * 0.10)
            + (max(0.0, 1.0 - market_balance) * 0.06)
            + (max(0.0, 1.0 - visual_coherence) * 0.06),
        ),
    )
    bearing = max(
        0.0,
        min(
            1.0,
            (structure_quality * 0.24)
            + (context_confidence * 0.18)
            + (visual_coherence * 0.16)
            + (market_balance * 0.12)
            + (stress_relief_potential * 0.10)
            + (field_clarity * 0.10)
            + (stability * 0.10),
        ),
    )
    fragility = max(
        0.0,
        min(
            1.0,
            (wick_pressure * 0.22)
            + (field_fragmentation * 0.20)
            + (field_pressure * 0.16)
            + (max(0.0, 1.0 - context_confidence) * 0.14)
            + (max(0.0, 1.0 - visual_coherence) * 0.12)
            + (max(0.0, 1.0 - stability) * 0.16),
        ),
    )
    resonance = max(0.0, min(1.0, maturity * stability * (1.0 - min(1.0, distance))))
    zoom_need = max(
        0.0,
        min(
            1.0,
            (relevance * 0.30)
            + (novelty * 0.22)
            + (fragility * 0.20)
            + (max(0.0, 0.42 - bearing) * 0.18)
            + (max(0.0, distance) * 0.10)
            + ((1.0 - form_resolution_quality) * form_detail_pressure * 0.08),
        ),
    )
    load_reduction = max(0.0, min(1.0, resonance * (1.0 - zoom_need) * (0.60 + stability * 0.40)))
    learned_development_quality = max(-1.0, min(1.0, float(item.get("development_quality", 0.0) or 0.0)))
    learned_action_affinity = max(0.0, min(1.0, float(item.get("action_affinity", 0.50) or 0.50)))
    learned_observation_affinity = max(0.0, min(1.0, float(item.get("observation_affinity", 0.0) or 0.0)))
    learned_reframe_potential = max(0.0, min(1.0, float(item.get("context_reframe_potential", 0.0) or 0.0)))
    learned_learning_trust = max(0.0, min(1.0, float(item.get("learning_trust", 0.0) or 0.0)))
    learned_action_trust = max(0.0, min(1.0, float(item.get("action_trust", 0.0) or 0.0)))
    learned_caution_trust = max(0.0, min(1.0, float(item.get("caution_trust", 0.0) or 0.0)))
    learned_contact_maturity = max(0.0, min(1.0, float(item.get("contact_maturity", 0.0) or 0.0)))
    learned_contact_utility = max(0.0, min(1.0, float(item.get("contact_utility", 0.0) or 0.0)))
    learned_contact_pain_memory = max(0.0, min(1.0, float(item.get("contact_pain_memory", 0.0) or 0.0)))
    learned_contact_carefulness = max(0.0, min(1.0, float(item.get("contact_carefulness", 0.0) or 0.0)))
    learned_contact_burden_evidence = max(0.0, min(1.0, float(item.get("contact_burden_evidence", 0.0) or 0.0)))
    learned_contact_utility_evidence = max(0.0, min(1.0, float(item.get("contact_utility_evidence", 0.0) or 0.0)))
    learned_contact_state = str(item.get("contact_learning_state", "unformed_contact") or "unformed_contact")
    symbolic_object_distance = max(
        0.0,
        min(
            1.0,
            maturity
            * stability
            * (0.45 + resonance * 0.55)
            * (0.45 + bearing * 0.55)
            * (1.0 - min(0.90, fragility * 0.72))
            * (0.65 + form_resolution_quality * 0.35),
        ),
    )
    symbolic_containment = max(
        0.0,
        min(
            1.0,
            (symbolic_object_distance * 0.58)
            + (load_reduction * 0.24)
            + (max(0.0, 1.0 - zoom_need) * 0.10)
            + (max(0.0, 1.0 - form_detail_pressure) * 0.08),
        ),
    )
    symbolic_field_decoupling = max(
        0.0,
        min(
            1.0,
            symbolic_containment
            * (0.40 + maturity * 0.28 + resonance * 0.20 + stability * 0.12)
            * (1.0 - min(0.78, fragility * 0.42)),
        ),
    )
    split_pressure = max(0.0, min(1.0, (variance * 0.52) + (novelty * 0.24) + (fragility * 0.18) - (stability * 0.10)))
    merge_pressure = max(0.0, min(1.0, (stability * 0.36) + (maturity * 0.30) + (resonance * 0.24) - (novelty * 0.18)))

    uncertain_form_exposure = max(
        0.0,
        min(
            1.0,
            (visual_blindness * 0.26)
            + (max(0.0, 0.42 - visual_clarity) * 0.18)
            + (max(0.0, 0.44 - visual_object_stability) * 0.16)
            + (visual_shape_fragility * 0.12)
            + (visual_form_pressure * 0.10)
            + (fragility * 0.10)
            + (max(0.0, 0.46 - bearing) * 0.14)
            + (visual_form_novelty * 0.06)
            - (visual_shape_resonance * 0.10)
            - (resonance * 0.06),
        ),
    )

    previous_state = dict(getattr(bot, "_last_form_symbol_state", {}) or {}) if bot is not None else {}
    previous_symbol_id = str(previous_state.get("form_symbol_id", "") or "").strip()
    compound_id = "-"
    compound_key = "-"
    compound_scope = "single"
    compound_seen = 0
    compound_maturity = 0.0
    compound_stability = 0.0
    compound_resonance = 0.0
    compound_bearing = 0.0
    compound_load_reduction = 0.0
    compound_novelty = 1.0
    compound_development_quality = 0.0
    compound_action_affinity = 0.50
    compound_observation_affinity = 0.0
    compound_reframe_potential = 0.0
    compound_learning_trust = 0.0
    compound_action_trust = 0.0
    compound_caution_trust = 0.0
    compound_contact_maturity = 0.0
    compound_contact_utility = 0.0
    compound_contact_pain_memory = 0.0
    compound_contact_carefulness = 0.0
    compound_contact_burden_evidence = 0.0
    compound_contact_utility_evidence = 0.0
    compound_contact_state = "unformed_contact"
    if previous_symbol_id and previous_symbol_id != "-" and previous_symbol_id != symbol_id and bot is not None:
        compound_scope = "compound_form"
        compound_key = f"{previous_symbol_id}>{symbol_id}"
        compound_digest = hashlib.sha1(str(compound_key).encode("utf-8")).hexdigest()[:10]
        compound_id = f"fc_{compound_digest}"
        compound_space = dict(getattr(bot, "form_symbol_compound_space", {}) or {})
        compound_item = dict(compound_space.get(compound_id, {}) or {})
        compound_seen = int(compound_item.get("seen", 0) or 0) + 1
        compound_maturity = max(0.0, min(1.0, compound_seen / float(compound_seen + 13)))
        previous_stability = float(previous_state.get("form_symbol_stability", 0.0) or 0.0)
        previous_resonance = float(previous_state.get("form_symbol_resonance", 0.0) or 0.0)
        previous_bearing = float(previous_state.get("form_symbol_bearing", 0.0) or 0.0)
        previous_resolution = float(previous_state.get("form_symbol_resolution_quality", 0.0) or 0.0)
        pair_balance = 1.0 - min(1.0, abs(previous_bearing - bearing))
        prior_compound_stability = float(compound_item.get("stability", 0.0) or 0.0)
        compound_stability = max(
            0.0,
            min(
                1.0,
                (prior_compound_stability * 0.70)
                + (((previous_stability + stability) * 0.50) * 0.20)
                + (pair_balance * 0.10),
            ),
        )
        compound_resonance = max(
            0.0,
            min(
                1.0,
                compound_maturity
                * compound_stability
                * (0.45 + ((previous_resonance + resonance) * 0.50) * 0.55),
            ),
        )
        compound_bearing = max(
            0.0,
            min(
                1.0,
                ((previous_bearing + bearing) * 0.50 * 0.54)
                + (compound_stability * 0.24)
                + (compound_resonance * 0.14)
                + (min(form_resolution_quality, previous_resolution) * 0.08),
            ),
        )
        compound_novelty = max(0.0, min(1.0, 1.0 - compound_maturity + (1.0 - pair_balance) * 0.20))
        compound_load_reduction = max(
            0.0,
            min(
                1.0,
                compound_resonance
                * (0.54 + compound_stability * 0.30 + compound_bearing * 0.16)
                * (1.0 - min(0.80, compound_novelty * 0.35)),
            ),
        )
        compound_development_quality = max(-1.0, min(1.0, float(compound_item.get("development_quality", 0.0) or 0.0)))
        compound_action_affinity = max(0.0, min(1.0, float(compound_item.get("action_affinity", 0.50) or 0.50)))
        compound_observation_affinity = max(0.0, min(1.0, float(compound_item.get("observation_affinity", 0.0) or 0.0)))
        compound_reframe_potential = max(0.0, min(1.0, float(compound_item.get("context_reframe_potential", 0.0) or 0.0)))
        compound_learning_trust = max(0.0, min(1.0, float(compound_item.get("learning_trust", 0.0) or 0.0)))
        compound_action_trust = max(0.0, min(1.0, float(compound_item.get("action_trust", 0.0) or 0.0)))
        compound_caution_trust = max(0.0, min(1.0, float(compound_item.get("caution_trust", 0.0) or 0.0)))
        compound_contact_maturity = max(0.0, min(1.0, float(compound_item.get("contact_maturity", 0.0) or 0.0)))
        compound_contact_utility = max(0.0, min(1.0, float(compound_item.get("contact_utility", 0.0) or 0.0)))
        compound_contact_pain_memory = max(0.0, min(1.0, float(compound_item.get("contact_pain_memory", 0.0) or 0.0)))
        compound_contact_carefulness = max(0.0, min(1.0, float(compound_item.get("contact_carefulness", 0.0) or 0.0)))
        compound_contact_burden_evidence = max(0.0, min(1.0, float(compound_item.get("contact_burden_evidence", 0.0) or 0.0)))
        compound_contact_utility_evidence = max(0.0, min(1.0, float(compound_item.get("contact_utility_evidence", 0.0) or 0.0)))
        compound_contact_state = str(compound_item.get("contact_learning_state", "unformed_contact") or "unformed_contact")
        compound_item.update({
            "compound_id": str(compound_id),
            "compound_key": str(compound_key),
            "left_symbol_id": str(previous_symbol_id),
            "right_symbol_id": str(symbol_id),
            "scope": str(compound_scope),
            "seen": int(compound_seen),
            "maturity": float(compound_maturity),
            "stability": float(compound_stability),
            "resonance": float(compound_resonance),
            "bearing": float(compound_bearing),
            "load_reduction": float(compound_load_reduction),
            "novelty": float(compound_novelty),
            "development_quality": float(compound_development_quality),
            "action_affinity": float(compound_action_affinity),
            "observation_affinity": float(compound_observation_affinity),
            "context_reframe_potential": float(compound_reframe_potential),
            "learning_trust": float(compound_learning_trust),
            "action_trust": float(compound_action_trust),
            "caution_trust": float(compound_caution_trust),
            "contact_maturity": float(compound_contact_maturity),
            "contact_utility": float(compound_contact_utility),
            "contact_pain_memory": float(compound_contact_pain_memory),
            "contact_carefulness": float(compound_contact_carefulness),
            "contact_burden_evidence": float(compound_contact_burden_evidence),
            "contact_utility_evidence": float(compound_contact_utility_evidence),
            "contact_learning_state": str(compound_contact_state),
            "first_seen_ts": compound_item.get("first_seen_ts", getattr(bot, "current_timestamp", None) if bot is not None else None),
            "last_seen_ts": getattr(bot, "current_timestamp", None) if bot is not None else None,
        })
        compound_space[compound_id] = dict(compound_item)
        bot.form_symbol_compound_space = dict(compound_space)

    learned_action_binding = max(
        0.0,
        min(
            1.0,
            (learned_action_affinity * 0.58)
            + (compound_action_affinity * 0.24 * max(0.0, min(1.0, compound_maturity)))
            + (bearing * 0.18)
            + (learned_action_trust * 0.08)
            - (learned_observation_affinity * 0.08)
            - (learned_reframe_potential * 0.05)
            - (learned_caution_trust * 0.18),
        ),
    )
    learned_observation_binding = max(
        0.0,
        min(
            1.0,
            (learned_observation_affinity * 0.62)
            + (compound_observation_affinity * 0.24 * max(0.0, min(1.0, compound_maturity)))
            + (fragility * 0.14),
        ),
    )
    learned_reframe_binding = max(
        0.0,
        min(
            1.0,
            (learned_reframe_potential * 0.60)
            + (compound_reframe_potential * 0.26 * max(0.0, min(1.0, compound_maturity)))
            + (max(0.0, 0.48 - bearing) * 0.14),
        ),
    )

    item.update({
        "symbol_id": str(symbol_id),
        "form_key": str(family_key),
        "family_key": str(family_key),
        "variant_key": str(form_key),
        "scope": str(form_symbol_scope),
        "abstraction_level": int(form_symbol_abstraction_level),
        "resolution_quality": float(form_resolution_quality),
        "detail_pressure": float(form_detail_pressure),
        "symbolic_object_distance": float(symbolic_object_distance),
        "symbolic_containment": float(symbolic_containment),
        "symbolic_field_decoupling": float(symbolic_field_decoupling),
        "development_quality": float(learned_development_quality),
        "action_affinity": float(learned_action_affinity),
        "observation_affinity": float(learned_observation_affinity),
        "context_reframe_potential": float(learned_reframe_potential),
        "learning_trust": float(learned_learning_trust),
        "action_trust": float(learned_action_trust),
        "caution_trust": float(learned_caution_trust),
        "seen": int(seen),
        "avg_vector": [float(v) for v in new_avg],
        "variance": float(variance),
        "maturity": float(maturity),
        "stability": float(stability),
        "resonance": float(resonance),
        "bearing": float(bearing),
        "fragility": float(fragility),
        "last_zoom_need": float(zoom_need),
        "last_load_reduction": float(load_reduction),
        "first_seen_ts": item.get("first_seen_ts", getattr(bot, "current_timestamp", None) if bot is not None else None),
        "last_seen_ts": getattr(bot, "current_timestamp", None) if bot is not None else None,
    })
    variants = dict(item.get("variants", {}) or {})
    variant_item = dict(variants.get(form_key, {}) or {})
    variant_item["seen"] = int(variant_item.get("seen", 0) or 0) + 1
    variant_item["distance"] = float(distance)
    variant_item["bearing"] = float(bearing)
    variant_item["fragility"] = float(fragility)
    variant_item["visual_blindness"] = float(visual_blindness)
    variant_item["visual_clarity"] = float(visual_clarity)
    variant_item["object_stability"] = float(visual_object_stability)
    variant_item["uncertain_exposure"] = float(uncertain_form_exposure)
    variant_item["last_seen_ts"] = getattr(bot, "current_timestamp", None) if bot is not None else None
    variants[str(form_key)] = dict(variant_item)
    max_variants = max(1, int(getattr(Config, "MCM_FORM_SYMBOL_MEMORY_MAX_VARIANTS", 12) or 12))
    item["variants"] = dict(
        sorted(
            variants.items(),
            key=lambda kv: int((kv[1] or {}).get("seen", 0) or 0) if isinstance(kv[1], dict) else 0,
            reverse=True,
        )[:max_variants]
    )
    variant_count = int(len(item.get("variants", {}) or {}))
    variant_seen_total = sum(
        int((variant or {}).get("seen", 0) or 0)
        for variant in dict(item.get("variants", {}) or {}).values()
        if isinstance(variant, dict)
    )
    variant_exposure_mean = 0.0
    variant_bearing_mean = 0.0
    if variant_count > 0:
        variant_exposure_mean = sum(
            float((variant or {}).get("uncertain_exposure", 0.0) or 0.0)
            for variant in dict(item.get("variants", {}) or {}).values()
            if isinstance(variant, dict)
        ) / float(max(1, variant_count))
        variant_bearing_mean = sum(
            float((variant or {}).get("bearing", 0.0) or 0.0)
            for variant in dict(item.get("variants", {}) or {}).values()
            if isinstance(variant, dict)
        ) / float(max(1, variant_count))
    variant_similarity = max(0.0, min(1.0, (1.0 - min(1.0, distance)) * 0.58 + stability * 0.28 + resonance * 0.14))
    variant_spread = max(
        0.0,
        min(
            1.0,
            (variance * 0.52)
            + (min(1.0, float(variant_count) / float(max(1, max_variants))) * 0.26)
            + (novelty * 0.12)
            + (visual_form_novelty * 0.10),
        ),
    )
    uncertainty_familiarity = max(
        0.0,
        min(
            1.0,
            (maturity * 0.34)
            + (min(1.0, float(variant_seen_total) / 24.0) * 0.24)
            + (variant_similarity * 0.18)
            + (learned_learning_trust * 0.14)
            + (variant_exposure_mean * 0.10),
        ),
    )
    variant_bearing_memory = max(
        0.0,
        min(
            1.0,
            (variant_bearing_mean * 0.32)
            + (bearing * 0.22)
            + (max(0.0, learned_development_quality) * 0.16)
            + (learned_action_trust * 0.14)
            + (resonance * 0.10)
            + (visual_shape_resonance * 0.06),
        ),
    )
    variant_learning_pressure = max(
        0.0,
        min(
            1.0,
            (uncertain_form_exposure * 0.32)
            + (variant_spread * 0.20)
            + (max(0.0, 0.52 - uncertainty_familiarity) * 0.20)
            + (max(0.0, 0.48 - variant_bearing_memory) * 0.16)
            + (learned_observation_affinity * 0.08)
            + (learned_reframe_potential * 0.04),
        ),
    )
    uncertain_form_family_state = "quiet_form_family"
    if uncertain_form_exposure >= 0.48 and uncertainty_familiarity < 0.28:
        uncertain_form_family_state = "unfamiliar_uncertain_family"
    elif uncertain_form_exposure >= 0.42 and variant_spread >= 0.42:
        uncertain_form_family_state = "recurring_uncertain_variants"
    elif uncertain_form_exposure >= 0.34 and uncertainty_familiarity >= 0.42 and variant_bearing_memory < 0.42:
        uncertain_form_family_state = "familiar_uncertainty_watch"
    elif uncertain_form_exposure >= 0.28 and variant_bearing_memory >= 0.48:
        uncertain_form_family_state = "bearing_uncertainty_family"

    semantic_density = max(
        0.0,
        min(
            1.0,
            (form_resolution_quality * 0.22)
            + (maturity * 0.16)
            + (stability * 0.14)
            + (resonance * 0.12)
            + (bearing * 0.14)
            + (symbolic_containment * 0.10)
            + (uncertainty_familiarity * 0.06)
            + (variant_similarity * 0.06)
            - (fragility * 0.08)
            - (variant_spread * 0.04),
        ),
    )
    semantic_compression = max(
        0.0,
        min(
            1.0,
            (load_reduction * 0.28)
            + (symbolic_object_distance * 0.22)
            + (symbolic_field_decoupling * 0.18)
            + (compound_load_reduction * 0.12)
            + (merge_pressure * 0.10)
            + (semantic_density * 0.10)
            - (zoom_need * 0.10)
            - (split_pressure * 0.06),
        ),
    )
    semantic_coherence = max(
        0.0,
        min(
            1.0,
            (semantic_density * 0.28)
            + (semantic_compression * 0.20)
            + (bearing * 0.16)
            + (stability * 0.14)
            + (context_confidence * 0.10)
            + (visual_coherence * 0.08)
            + (field_clarity * 0.04)
            - (field_fragmentation * 0.10)
            - (fragility * 0.08),
        ),
    )
    semantic_learning_need = max(
        0.0,
        min(
            1.0,
            (variant_learning_pressure * 0.26)
            + (zoom_need * 0.20)
            + (novelty * 0.16)
            + (uncertain_form_exposure * 0.14)
            + (split_pressure * 0.10)
            + (max(0.0, 0.48 - semantic_coherence) * 0.10)
            + (max(0.0, 0.44 - semantic_compression) * 0.04),
        ),
    )
    semantic_action_nearness = max(
        0.0,
        min(
            1.0,
            (learned_action_binding * 0.26)
            + (variant_bearing_memory * 0.18)
            + (bearing * 0.16)
            + (semantic_coherence * 0.14)
            + (compound_bearing * 0.10)
            + (symbolic_field_decoupling * 0.08)
            + (learned_action_trust * 0.08)
            - (learned_caution_trust * 0.10)
            - (semantic_learning_need * 0.08),
        ),
    )
    semantic_primary_layer = "trace_layer"
    if semantic_action_nearness >= 0.56 and semantic_coherence >= 0.48:
        semantic_primary_layer = "action_near_layer"
    elif semantic_learning_need >= 0.46 and uncertainty_familiarity < 0.48:
        semantic_primary_layer = "learning_layer"
    elif learned_observation_binding >= max(learned_action_binding, learned_reframe_binding) and learned_observation_binding >= 0.32:
        semantic_primary_layer = "observation_layer"
    elif learned_reframe_binding >= 0.30 or symbolic_field_decoupling >= 0.44:
        semantic_primary_layer = "reflective_layer"
    elif symbolic_object_distance >= 0.42 and semantic_density >= 0.46:
        semantic_primary_layer = "object_layer"
    elif form_symbol_scope == "structured_form":
        semantic_primary_layer = "structured_form_layer"
    elif form_symbol_scope == "wide_form":
        semantic_primary_layer = "wide_form_layer"
    semantic_layer_count = 1
    for layer_value in (
        semantic_density,
        semantic_compression,
        symbolic_object_distance,
        learned_observation_binding,
        learned_reframe_binding,
        semantic_action_nearness,
        compound_maturity,
        uncertainty_familiarity,
    ):
        if float(layer_value) >= 0.34:
            semantic_layer_count += 1
    semantic_layer_count = int(max(1, min(8, semantic_layer_count)))
    semantic_packet_state = "thin_trace"
    if semantic_action_nearness >= 0.58 and semantic_coherence >= 0.52:
        semantic_packet_state = "action_bearing_packet"
    elif semantic_compression >= 0.52 and semantic_coherence >= 0.48:
        semantic_packet_state = "condensed_object_packet"
    elif semantic_learning_need >= 0.50:
        semantic_packet_state = "open_learning_packet"
